/**
 * Bibliography Preview Modal
 * Shows a preview of the bibliography before inserting
 */

import * as React from "react";
import {
  Dialog,
  DialogSurface,
  DialogBody,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Spinner,
  makeStyles,
  shorthands,
} from "@fluentui/react-components";
import { designTokens } from "../theme";
import { CitationStyle, BibLanguage, Source } from "../types/fishchi";
import { apiFormatBibliography } from "../services/api";
import { bibFormattingService } from "../services/bibliographyFormattingService";

const useStyles = makeStyles({
  preview: {
    ...shorthands.padding(designTokens.spacing.md),
    backgroundColor: designTokens.colors.surface,
    ...shorthands.borderRadius(designTokens.borderRadius.md),
    maxHeight: "400px",
    overflowY: "auto",
    fontFamily: "Georgia, serif",
    fontSize: "14px",
    lineHeight: "1.8",
    "& p": {
      marginBottom: designTokens.spacing.sm,
    },
  },
  loading: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    ...shorthands.padding(designTokens.spacing.xl),
  },
});

interface BibliographyPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  citedSourceIds: Set<string>;
  sources: Source[];
  style: CitationStyle;
  language: BibLanguage;
  onInsert: () => void;
}

export const BibliographyPreviewModal: React.FC<BibliographyPreviewModalProps> = ({
  isOpen,
  onClose,
  citedSourceIds,
  sources,
  style,
  language,
  onInsert,
}) => {
  const styles = useStyles();
  const [preview, setPreview] = React.useState<string>("");
  const [isLoading, setIsLoading] = React.useState(false);

  React.useEffect(() => {
    if (isOpen && citedSourceIds.size > 0) {
      loadPreview();
    }
  }, [isOpen, citedSourceIds, style, language]);

  const loadPreview = async () => {
    setIsLoading(true);
    try {
      const sourceIds = Array.from(citedSourceIds);
      const citedSources = sources.filter((s) => sourceIds.includes(s._id));

      const bibHtml = await bibFormattingService.formatBibliographyWithSections(
        citedSources,
        sourceIds,
        style,
        language
      );

      setPreview(bibHtml);
    } catch (error) {
      console.error("Failed to load preview:", error);
      setPreview("<p>خطا در بارگذاری پیش‌نمایش</p>");
    } finally {
      setIsLoading(false);
    }
  };

  const handleInsert = () => {
    onInsert();
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={(_, data) => !data.open && onClose()}>
      <DialogSurface style={{ maxWidth: "700px" }}>
        <DialogBody>
          <DialogTitle>پیش‌نمایش کتابنامه</DialogTitle>
          <DialogContent>
            {isLoading ? (
              <div className={styles.loading}>
                <Spinner label="در حال بارگذاری پیش‌نمایش..." />
              </div>
            ) : (
              <div className={styles.preview} dangerouslySetInnerHTML={{ __html: preview }} />
            )}
          </DialogContent>
          <DialogActions>
            <Button appearance="secondary" onClick={onClose}>
              بستن
            </Button>
            <Button appearance="primary" onClick={handleInsert} disabled={isLoading}>
              درج کتابنامه
            </Button>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  );
};
