/**
 * Service for navigating to citation locations in the document
 */

/* global Word */

export const navigateToCitation = async (sourceId: string, locationId: string): Promise<void> => {
  try {
    await Word.run(async (context) => {
      // Find all citation content controls for this source
      const controls = context.document.contentControls.getByTag(`FISHCHI_CITATION_${sourceId}`);
      context.load(controls, "items");
      await context.sync();

      if (controls.items.length === 0) {
        console.warn(`No citation found for source: ${sourceId}`);
        return;
      }

      // Parse locationId to get the citation index
      // locationId format: "sourceId_citationNumber_index"
      const parts = locationId.split("_");
      const citationNumber = parts.length >= 2 ? parseInt(parts[1]) : 1;
      const citationIndex = citationNumber - 1; // Convert to 0-based index

      console.log(
        `Navigating to citation ${citationNumber} (index ${citationIndex}) of ${controls.items.length} total`
      );

      // Select the specific citation by index
      if (citationIndex >= 0 && citationIndex < controls.items.length) {
        const citation = controls.items[citationIndex];
        citation.select();

        // Highlight temporarily
        const range = citation.getRange();
        range.font.highlightColor = "#fff100"; // Yellow highlight

        await context.sync();

        // Remove highlight after 2 seconds
        setTimeout(async () => {
          try {
            await Word.run(async (ctx) => {
              const r = ctx.document.getSelection();
              r.font.highlightColor = null;
              await ctx.sync();
            });
          } catch (err) {
            console.warn("Could not remove highlight:", err);
          }
        }, 2000);
      } else {
        console.warn(
          `Citation index ${citationIndex} out of range (0-${controls.items.length - 1})`
        );
        // Fallback to first citation
        const citation = controls.items[0];
        citation.select();
        await context.sync();
      }
    });
  } catch (error) {
    console.error("Error navigating to citation:", error);
    throw error;
  }
};
