import * as React from "react";
import {
  Dialog,
  DialogSurface,
  DialogBody,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Field,
  Textarea,
  Text,
  MessageBar,
  MessageBarBody,
  Spinner,
  makeStyles,
  shorthands,
} from "@fluentui/react-components";
import { Source } from "../types/fishchi";
import { designTokens } from "../theme";

const useStyles = makeStyles({
  quoteForm: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.md),
  },
  sourceInfo: {
    ...shorthands.padding(designTokens.spacing.sm),
    backgroundColor: designTokens.colors.surface,
    ...shorthands.borderRadius(designTokens.borderRadius.sm),
  },
  previewBox: {
    ...shorthands.padding(designTokens.spacing.sm),
    backgroundColor: "#f5f5f5",
    ...shorthands.borderRadius(designTokens.borderRadius.sm),
    fontStyle: "italic",
    fontSize: "13px",
    lineHeight: "1.6",
  },
});

interface DirectQuoteModalProps {
  isOpen: boolean;
  onClose: () => void;
  source: Source | null;
  onInsert: (quoteText: string) => Promise<void>;
}

export const DirectQuoteModal: React.FC<DirectQuoteModalProps> = ({
  isOpen,
  onClose,
  source,
  onInsert,
}) => {
  const styles = useStyles();
  const [quoteText, setQuoteText] = React.useState("");
  const [isInserting, setIsInserting] = React.useState(false);

  const handleInsert = async () => {
    // Allow empty quote text - user can insert citation without quote
    setIsInserting(true);
    try {
      await onInsert(quoteText);
      onClose();
      setQuoteText("");
    } catch (error) {
      console.error("Failed to insert quote:", error);
    } finally {
      setIsInserting(false);
    }
  };

  if (!source) return null;

  // Format author name for preview
  const authorName =
    source.authors.length > 0
      ? source.authors[0].lastname + (source.authors.length > 1 ? " و همکاران" : "")
      : "نویسنده نامشخص";

  const year = source.year || "بدون تاریخ";

  return (
    <Dialog open={isOpen} onOpenChange={(_, data) => !data.open && onClose()}>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>درج نقل قول مستقیم</DialogTitle>
          <DialogContent>
            <div className={styles.quoteForm}>
              {/* Source Information */}
              <div className={styles.sourceInfo}>
                <Text weight="semibold" block>
                  {source.title}
                </Text>
                <Text size={200} block>
                  {source.authors.map((a) => a.lastname).join("، ")} ({year})
                </Text>
              </div>

              {/* Quote Text Input */}
              <Field label="متن نقل قول (اختیاری)">
                <Textarea
                  value={quoteText}
                  onChange={(_, data) => setQuoteText(data.value)}
                  placeholder="متن نقل قول را وارد کنید (اختیاری - می‌توانید خالی بگذارید)"
                  rows={5}
                  disabled={isInserting}
                  aria-label="متن نقل قول"
                  aria-describedby="quote-preview"
                />
              </Field>

              {/* Preview */}
              <div id="quote-preview" role="region" aria-label="پیش‌نمایش نقل قول">
                <Text size={200} weight="semibold" block style={{ marginBottom: "4px" }}>
                  پیش‌نمایش:
                </Text>
                <div className={styles.previewBox} aria-live="polite">
                  {authorName} ({year}){quoteText.trim() && `، "${quoteText}"`}
                </div>
              </div>

              {/* Information Message */}
              <MessageBar intent="info">
                <MessageBarBody>
                  {quoteText.trim()
                    ? 'نقل قول با فرمت: نویسنده (سال)، "متن نقل قول" درج خواهد شد'
                    : "استناد با فرمت: نویسنده (سال) درج خواهد شد"}
                  {source.language &&
                  !["persian", "fa", "fa-IR"].includes(source.language.toLowerCase())
                    ? " و نام اصلی نویسندگان به عنوان زیرنویس اضافه می‌شود"
                    : ""}
                  .
                </MessageBarBody>
              </MessageBar>
            </div>
          </DialogContent>
          <DialogActions>
            <Button appearance="secondary" onClick={onClose} disabled={isInserting}>
              انصراف
            </Button>
            <Button appearance="primary" onClick={handleInsert} disabled={isInserting}>
              {isInserting ? <Spinner size="tiny" /> : "درج نقل قول"}
            </Button>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  );
};
