/**
 * useKeyboardShortcuts Hook
 * Handles keyboard shortcuts for common actions
 */

import { useEffect } from "react";

export interface KeyboardShortcutHandlers {
  onInsertCitation?: () => void;
  onInsertBibliography?: () => void;
  onRefresh?: () => void;
  onSearch?: () => void;
}

export const useKeyboardShortcuts = (handlers: KeyboardShortcutHandlers) => {
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // Check for Ctrl+Shift combinations (or Cmd+Shift on Mac)
      const isModifier = event.ctrlKey || event.metaKey;
      const isShift = event.shiftKey;

      if (!isModifier || !isShift) return;

      switch (event.key.toUpperCase()) {
        case "C":
          // Ctrl+Shift+C: Insert Citation
          if (handlers.onInsertCitation) {
            event.preventDefault();
            handlers.onInsertCitation();
          }
          break;

        case "B":
          // Ctrl+Shift+B: Insert Bibliography
          if (handlers.onInsertBibliography) {
            event.preventDefault();
            handlers.onInsertBibliography();
          }
          break;

        case "R":
          // Ctrl+Shift+R: Refresh
          if (handlers.onRefresh) {
            event.preventDefault();
            handlers.onRefresh();
          }
          break;

        case "F":
          // Ctrl+Shift+F: Focus Search
          if (handlers.onSearch) {
            event.preventDefault();
            handlers.onSearch();
          }
          break;

        default:
          break;
      }
    };

    // Add event listener
    document.addEventListener("keydown", handleKeyDown);

    // Cleanup
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [handlers]);
};
