/**
 * Citation History Service
 * Tracks citation insertion history for undo/redo functionality
 */

export interface CitationHistoryEntry {
  id: string;
  sourceId: string;
  sourceTitle: string;
  action: "insert" | "remove" | "update";
  timestamp: Date;
  style: string;
  translated: boolean;
}

class CitationHistoryService {
  private history: CitationHistoryEntry[] = [];
  private maxHistorySize = 50;

  /**
   * Add an entry to history
   */
  addEntry(entry: Omit<CitationHistoryEntry, "id" | "timestamp">): void {
    const newEntry: CitationHistoryEntry = {
      ...entry,
      id: `history-${Date.now()}-${Math.random()}`,
      timestamp: new Date(),
    };

    this.history.unshift(newEntry);

    // Keep only last N entries
    if (this.history.length > this.maxHistorySize) {
      this.history = this.history.slice(0, this.maxHistorySize);
    }

    console.log("Citation history entry added:", newEntry);
  }

  /**
   * Get all history entries
   */
  getHistory(): CitationHistoryEntry[] {
    return [...this.history];
  }

  /**
   * Get recent history (last N entries)
   */
  getRecentHistory(count: number = 10): CitationHistoryEntry[] {
    return this.history.slice(0, count);
  }

  /**
   * Clear all history
   */
  clearHistory(): void {
    this.history = [];
    console.log("Citation history cleared");
  }

  /**
   * Get history for a specific source
   */
  getHistoryForSource(sourceId: string): CitationHistoryEntry[] {
    return this.history.filter((entry) => entry.sourceId === sourceId);
  }

  /**
   * Get statistics
   */
  getStatistics() {
    const totalInsertions = this.history.filter((e) => e.action === "insert").length;
    const totalRemovals = this.history.filter((e) => e.action === "remove").length;
    const totalTranslated = this.history.filter((e) => e.translated).length;

    return {
      totalInsertions,
      totalRemovals,
      totalTranslated,
      totalEntries: this.history.length,
    };
  }
}

export const citationHistoryService = new CitationHistoryService();
