/**
 * Service for converting citation styles
 * Handles conversion of all citations and bibliography to a new style
 */

/* global Word */

import { CitationStyle, Source } from "../types/fishchi";
import { apiFormatCitation, apiTranslateText } from "./api";
import { insertOrReplaceBibliography } from "./wordService";
import { footnoteService } from "./citationFootnoteService";
import { vancouverService } from "./vancouverNumberingService";

interface ConversionResult {
  convertedCitations: number;
  convertedBibliography: boolean;
  skippedDirectQuotes: number;
  errors: string[];
}

interface ScannedCitation {
  sourceId: string;
  contentControlId: number;
  isDirectQuote: boolean;
  currentText: string;
}

class StyleConversionService {
  /**
   * Converts all citations and bibliography to a new style
   */
  async convertCitationStyle(
    fromStyle: CitationStyle,
    toStyle: CitationStyle,
    translateToFarsi: boolean,
    sources: Source[]
  ): Promise<ConversionResult> {
    const result: ConversionResult = {
      convertedCitations: 0,
      convertedBibliography: false,
      skippedDirectQuotes: 0,
      errors: [],
    };

    try {
      console.log(`Converting from ${fromStyle} to ${toStyle}, translate: ${translateToFarsi}`);

      // Step 1: Scan document for citations
      const citations = await this.scanAllCitations();
      console.log(`Found ${citations.length} citations`);

      // Step 2: Convert each citation (except direct quotes)
      const processedSources = new Set<string>(); // Track which sources we've seen

      for (const citation of citations) {
        if (citation.isDirectQuote) {
          result.skippedDirectQuotes++;
          console.log(`Skipping direct quote for source ${citation.sourceId}`);
          continue;
        }

        try {
          const isFirstOccurrence = !processedSources.has(citation.sourceId);
          await this.convertSingleCitation(
            citation,
            toStyle,
            translateToFarsi,
            sources,
            isFirstOccurrence
          );
          processedSources.add(citation.sourceId);
          result.convertedCitations++;
        } catch (error: any) {
          result.errors.push(`Failed to convert citation ${citation.sourceId}: ${error.message}`);
          console.error(`Error converting citation ${citation.sourceId}:`, error);
        }
      }

      // Step 2.5: Insert actual footnotes in Word for first occurrences
      if (translateToFarsi && toStyle.toLowerCase() !== "vancouver") {
        await this.insertFootnotesInWord(citations, sources);
      }

      // Step 3: Convert bibliography
      try {
        const sourceIds = citations.filter((c) => !c.isDirectQuote).map((c) => c.sourceId);
        const uniqueSourceIds = Array.from(new Set(sourceIds));

        await this.convertBibliography(uniqueSourceIds, toStyle, translateToFarsi);
        result.convertedBibliography = true;
      } catch (error: any) {
        result.errors.push(`Failed to convert bibliography: ${error.message}`);
        console.error("Error converting bibliography:", error);
      }

      console.log("Conversion result:", result);
      return result;
    } catch (error: any) {
      throw new Error(`Style conversion failed: ${error.message}`);
    }
  }

  /**
   * Scans document for all citations
   */
  private async scanAllCitations(): Promise<ScannedCitation[]> {
    return await Word.run(async (context) => {
      const contentControls = context.document.contentControls;
      contentControls.load("items");
      await context.sync();

      const citations: ScannedCitation[] = [];

      for (const control of contentControls.items) {
        context.load(control, ["tag", "text", "title", "id"]);
        await context.sync();

        if (control.tag?.startsWith("FISHCHI_CITATION_")) {
          const sourceId = control.tag.replace("FISHCHI_CITATION_", "");
          const isDirectQuote = control.title?.includes("DIRECT_QUOTE") || false;

          citations.push({
            sourceId,
            contentControlId: control.id,
            isDirectQuote,
            currentText: control.text,
          });
        }
      }

      return citations;
    });
  }

  /**
   * Converts a single citation to new style
   */
  private async convertSingleCitation(
    citation: ScannedCitation,
    toStyle: CitationStyle,
    translateToFarsi: boolean,
    sources: Source[],
    isFirstOccurrence: boolean
  ): Promise<void> {
    // Get new formatted citation
    const formatted = await apiFormatCitation({
      sourceId: citation.sourceId,
      style: toStyle,
    });

    let newText = formatted.inText;

    // Handle Vancouver style
    if (toStyle.toLowerCase() === "vancouver") {
      const number = await vancouverService.insertCitationWithNumber(citation.sourceId);
      newText = `[${number}]`;
    } else {
      // Translate if requested
      if (translateToFarsi) {
        newText = await apiTranslateText(newText, "Persian");

        // Prepare footnote for non-Vancouver styles and non-Persian sources (only first occurrence)
        const source = sources.find((s) => s._id === citation.sourceId);
        if (source && isFirstOccurrence) {
          // Check if source is non-Persian
          const isNonPersian =
            !source.language || !["persian", "fa", "fa-IR"].includes(source.language.toLowerCase());

          if (isNonPersian) {
            await footnoteService.prepareFootnoteForTranslation(citation.sourceId, source, toStyle);
            // Note: We don't insert the footnote number into the citation text
            // The footnote will be added separately
          }
        }
      }
    }

    // Update content control
    await this.updateContentControl(citation.contentControlId, newText);
  }

  /**
   * Updates a content control with new text
   */
  private async updateContentControl(controlId: number, newText: string): Promise<void> {
    await Word.run(async (context) => {
      const controls = context.document.contentControls;
      controls.load("items");
      await context.sync();

      const control = controls.items.find((c) => c.id === controlId);
      if (control) {
        control.clear();
        control.insertText(newText, Word.InsertLocation.start);
        await context.sync();
      }
    });
  }

  /**
   * Inserts actual footnotes in Word for first occurrences of each source
   */
  private async insertFootnotesInWord(
    citations: ScannedCitation[],
    sources: Source[]
  ): Promise<void> {
    await Word.run(async (context) => {
      const allFootnotes = footnoteService.getAllFootnotes();

      // For each footnote that needs to be inserted
      for (const footnoteData of allFootnotes) {
        // Find the first citation for this source
        const firstCitation = citations.find((c) => c.sourceId === footnoteData.sourceId);
        if (!firstCitation) continue;

        // Find the content control
        const controls = context.document.contentControls;
        controls.load("items");
        await context.sync();

        const control = controls.items.find((c) => c.id === firstCitation.contentControlId);
        if (control) {
          // Get the range at the end of the citation
          const range = control.getRange(Word.RangeLocation.end);

          // Insert the footnote
          const footnote = range.insertFootnote();
          footnote.body.insertText(footnoteData.originalAuthors, Word.InsertLocation.start);

          await context.sync();
          console.log(
            `Inserted footnote for source ${footnoteData.sourceId}: ${footnoteData.originalAuthors}`
          );
        }
      }
    });
  }

  /**
   * Converts bibliography to new style
   */
  private async convertBibliography(
    sourceIds: string[],
    toStyle: CitationStyle,
    translateToFarsi: boolean
  ): Promise<void> {
    const lang = translateToFarsi ? "fa-IR" : "auto";

    // For Vancouver, use ordered source IDs
    let orderedIds = sourceIds;
    if (toStyle.toLowerCase() === "vancouver") {
      await vancouverService.scanAndNumberCitations();
      orderedIds = vancouverService.getOrderedSourceIds();
    }

    // Import apiFormatBibliography
    const { apiFormatBibliography } = await import("./api");

    const bibHtml = await apiFormatBibliography(
      orderedIds,
      toStyle,
      lang as "fa-IR" | "en-US" | "auto"
    );

    await insertOrReplaceBibliography(bibHtml, orderedIds, toStyle);
  }
}

export const conversionService = new StyleConversionService();
