/**
 * Notification Service
 * Manages user notifications with different types and auto-dismiss
 */

export enum NotificationType {
  SUCCESS = "success",
  ERROR = "error",
  WARNING = "warning",
  INFO = "info",
}

export interface Notification {
  id: string;
  type: NotificationType;
  title: string;
  message: string;
  duration?: number; // in milliseconds, 0 means no auto-dismiss
  actions?: NotificationAction[];
}

export interface NotificationAction {
  label: string;
  action: () => void;
  appearance?: "primary" | "secondary";
}

type NotificationListener = (notifications: Notification[]) => void;

class NotificationService {
  private notifications: Notification[] = [];
  private listeners: NotificationListener[] = [];
  private nextId = 1;

  /**
   * Subscribe to notification changes
   */
  subscribe(listener: NotificationListener): () => void {
    this.listeners.push(listener);
    // Return unsubscribe function
    return () => {
      const index = this.listeners.indexOf(listener);
      if (index > -1) {
        this.listeners.splice(index, 1);
      }
    };
  }

  /**
   * Notify all listeners of changes
   */
  private notifyListeners(): void {
    this.listeners.forEach((listener) => listener([...this.notifications]));
  }

  /**
   * Add a new notification
   */
  private addNotification(notification: Omit<Notification, "id">): string {
    const id = `notification-${this.nextId++}`;
    const newNotification: Notification = {
      ...notification,
      id,
      duration: notification.duration ?? 5000, // Default 5 seconds
    };

    this.notifications.push(newNotification);
    this.notifyListeners();

    // Auto-dismiss if duration is set
    if (newNotification.duration && newNotification.duration > 0) {
      setTimeout(() => {
        this.dismiss(id);
      }, newNotification.duration);
    }

    return id;
  }

  /**
   * Show success notification
   */
  success(title: string, message: string, duration?: number): string {
    return this.addNotification({
      type: NotificationType.SUCCESS,
      title,
      message,
      duration,
    });
  }

  /**
   * Show error notification
   */
  error(title: string, message: string, actions?: NotificationAction[]): string {
    return this.addNotification({
      type: NotificationType.ERROR,
      title,
      message,
      duration: 0, // Errors don't auto-dismiss
      actions,
    });
  }

  /**
   * Show warning notification
   */
  warning(title: string, message: string, duration?: number): string {
    return this.addNotification({
      type: NotificationType.WARNING,
      title,
      message,
      duration: duration ?? 7000, // Warnings stay longer
    });
  }

  /**
   * Show info notification
   */
  info(title: string, message: string, duration?: number): string {
    return this.addNotification({
      type: NotificationType.INFO,
      title,
      message,
      duration,
    });
  }

  /**
   * Dismiss a notification by ID
   */
  dismiss(id: string): void {
    const index = this.notifications.findIndex((n) => n.id === id);
    if (index > -1) {
      this.notifications.splice(index, 1);
      this.notifyListeners();
    }
  }

  /**
   * Clear all notifications
   */
  clear(): void {
    this.notifications = [];
    this.notifyListeners();
  }

  /**
   * Get current notifications
   */
  getNotifications(): Notification[] {
    return [...this.notifications];
  }

  /**
   * Show citation operation success
   */
  citationSuccess(operation: string): string {
    return this.success("موفقیت", `${operation} با موفقیت انجام شد`);
  }

  /**
   * Show citation operation error
   */
  citationError(operation: string, error: string): string {
    return this.error("خطا در عملیات استناد", `${operation} با خطا مواجه شد: ${error}`, [
      {
        label: "تلاش مجدد",
        action: () => {
          // This will be handled by the calling component
        },
        appearance: "primary",
      },
    ]);
  }

  /**
   * Show network error with retry option
   */
  networkError(retryFn?: () => void): string {
    return this.error(
      "خطای شبکه",
      "ارتباط با سرور برقرار نشد. لطفاً اتصال اینترنت خود را بررسی کنید.",
      retryFn
        ? [
            {
              label: "تلاش مجدد",
              action: retryFn,
              appearance: "primary",
            },
          ]
        : undefined
    );
  }

  /**
   * Show authentication error
   */
  authError(): string {
    return this.error("خطای احراز هویت", "نشست شما منقضی شده است. لطفاً دوباره وارد شوید.", [
      {
        label: "ورود مجدد",
        action: () => {
          // Redirect to login or refresh token
          window.location.reload();
        },
        appearance: "primary",
      },
    ]);
  }
}

export const notificationService = new NotificationService();
