/**
 * Hook for tracking sources cited in the current document
 */

import { useState, useCallback, useEffect } from "react";
import { Source } from "../types/fishchi";
import { DocumentSource, CitationLocation } from "../types/documentSources";
import { scanDocumentForCitations } from "../services/wordService";

export const useDocumentSources = (sources: Source[]) => {
  const [documentSources, setDocumentSources] = useState<DocumentSource[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  const scanDocument = useCallback(async () => {
    setIsScanning(true);
    try {
      // Get all cited source IDs from the document (including duplicates)
      const citedSourceIds = await scanDocumentForCitations();

      console.log("Scanned citations:", citedSourceIds);

      // Build document sources map
      const sourcesMap = new Map<string, DocumentSource>();

      // Count occurrences of each source
      citedSourceIds.forEach((sourceId, index) => {
        const source = sources.find((s) => s._id === sourceId);
        if (!source) return;

        if (!sourcesMap.has(sourceId)) {
          sourcesMap.set(sourceId, {
            sourceId: sourceId,
            source: source,
            citationCount: 0,
            citationLocations: [],
            firstCitedAt: new Date(),
            lastCitedAt: new Date(),
          });
        }

        const docSource = sourcesMap.get(sourceId)!;
        docSource.citationCount++;

        // Create citation location
        const location: CitationLocation = {
          id: `${sourceId}_${docSource.citationCount}_${index}`,
          paragraphIndex: index,
          rangeStart: 0,
          rangeEnd: 0,
          text: `استناد ${docSource.citationCount}`,
          timestamp: new Date(),
        };

        docSource.citationLocations.push(location);
        docSource.lastCitedAt = new Date();
      });

      const result = Array.from(sourcesMap.values());
      console.log("Document sources:", result);
      setDocumentSources(result);
    } catch (error) {
      console.error("Error scanning document:", error);
      setDocumentSources([]);
    } finally {
      setIsScanning(false);
    }
  }, [sources]);

  useEffect(() => {
    if (sources.length > 0) {
      scanDocument();
    }
  }, [sources, scanDocument]);

  return {
    documentSources,
    isScanning,
    refreshDocumentSources: scanDocument,
  };
};
