import * as React from "react";
import { Source, CitationStyle } from "../types/fishchi";
import { apiFormatCitation, apiFormatBibliography, apiTranslateText } from "../services/api";
import {
  insertCitationWithTracking,
  insertOrReplaceBibliography,
  removeCitation,
  removeBibliography,
  clearCitationTracking,
  getCitedSourceIds,
  insertFootnote,
  getUniqueCitedSourceIds,
} from "../services/wordService";
import { BibLanguage } from "../types/fishchi";
import { footnoteService } from "../services/citationFootnoteService";
import { vancouverService } from "../services/vancouverNumberingService";
import { highlightingService } from "../services/paragraphHighlightingService";
import { bibFormattingService } from "../services/bibliographyFormattingService";
import { notificationService } from "../services/notificationService";

interface UseCitationsReturn {
  citedSourceIds: Set<string>;
  setCitedSourceIds: React.Dispatch<React.SetStateAction<Set<string>>>;
  selectedStyle: CitationStyle;
  setSelectedStyle: React.Dispatch<React.SetStateAction<CitationStyle>>;
  bibLanguage: BibLanguage;
  setBibLanguage: React.Dispatch<React.SetStateAction<BibLanguage>>;
  autoUpdateBib: boolean;
  setAutoUpdateBib: React.Dispatch<React.SetStateAction<boolean>>;
  isInserting: string | null;
  isInsertingBib: boolean;
  translatedFootnotesAdded: Set<string>;
  setTranslatedFootnotesAdded: React.Dispatch<React.SetStateAction<Set<string>>>;
  insertCitation: (sourceId: string, shouldTranslate?: boolean) => Promise<void>;
  insertDirectQuote: (sourceId: string, quoteText: string) => Promise<void>;
  removeCitationHandler: (sourceId: string) => Promise<void>;
  insertBibliography: () => Promise<void>;
  clearAllCitations: () => Promise<void>;
  clearBibliography: () => Promise<void>;
  renumberVancouver: () => Promise<void>;
  updateBibliography: (overrideIds?: Set<string>) => Promise<void>;
}

export const useCitations = (
  sources: Source[],
  setError: (error: string | null) => void
): UseCitationsReturn => {
  const [citedSourceIds, setCitedSourceIds] = React.useState<Set<string>>(new Set());
  const [selectedStyle, setSelectedStyle] = React.useState<CitationStyle>("apa");
  const [bibLanguage, setBibLanguage] = React.useState<BibLanguage>("fa-IR");
  const [autoUpdateBib, setAutoUpdateBib] = React.useState(true);
  const [isInserting, setIsInserting] = React.useState<string | null>(null);
  const [isInsertingBib, setIsInsertingBib] = React.useState(false);
  const [translatedFootnotesAdded, setTranslatedFootnotesAdded] = React.useState<Set<string>>(
    new Set()
  );

  // Update bibliography function
  const updateBibliography = React.useCallback(
    async (overrideIds?: Set<string>) => {
      const idsToUse = overrideIds || citedSourceIds;

      // Skip auto-update for Vancouver style
      if (!autoUpdateBib || selectedStyle.toLowerCase() === "vancouver") {
        if (selectedStyle.toLowerCase() === "vancouver") {
          console.log('Vancouver: Skipping auto-update. Use manual "درج کتابنامه" button.');
        }
        if (autoUpdateBib && idsToUse.size === 0) {
          await removeBibliography();
        }
        return;
      }

      if (idsToUse.size === 0) {
        await removeBibliography();
        return;
      }

      try {
        const citedSources = sources.filter((s) => citedSourceIds.has(s._id));
        const hasPersianSources = citedSources.some(
          (s) => s.language === "persian" || s.language === "fa" || s.language === "fa-IR"
        );

        const finalLang =
          hasPersianSources && bibLanguage === "fa-IR"
            ? "fa-IR"
            : !hasPersianSources && bibLanguage === "en-US"
              ? "en-US"
              : "auto";

        const bibHtml = await apiFormatBibliography(
          Array.from(idsToUse),
          selectedStyle,
          finalLang as "fa-IR" | "en-US" | "auto"
        );

        await insertOrReplaceBibliography(bibHtml, Array.from(idsToUse), selectedStyle);
      } catch (err: any) {
        console.error("Auto bibliography update failed:", err);
      }
    },
    [citedSourceIds, selectedStyle, bibLanguage, autoUpdateBib, sources]
  );

  // Insert citation handler
  const insertCitation = React.useCallback(
    async (sourceId: string, shouldTranslate: boolean = false) => {
      if (isInserting) return;

      const loadingKey = shouldTranslate ? `${sourceId}_translate` : sourceId;
      setIsInserting(loadingKey);
      setError(null);

      try {
        const source = sources.find((s) => s._id === sourceId);
        if (!source) {
          throw new Error("Source not found");
        }

        let inTextToInsert: string;
        let footnoteNumber: number | null = null;
        let footnoteText: string | null = null;

        // Handle Vancouver style differently
        if (selectedStyle.toLowerCase() === "vancouver") {
          // Get or assign Vancouver number
          const number = await vancouverService.insertCitationWithNumber(sourceId);
          inTextToInsert = `[${number}]`;
          console.log(`Vancouver citation: [${number}] for source ${sourceId}`);
        } else {
          // Regular citation formatting
          const formattedCitation = await apiFormatCitation({
            sourceId: sourceId,
            style: selectedStyle,
          });
          inTextToInsert = formattedCitation.inText;

          // Prepare footnote text for translated citations
          if (shouldTranslate) {
            footnoteText = await footnoteService.prepareFootnoteForTranslation(
              sourceId,
              source,
              selectedStyle
            );
            // Get the footnote number that was assigned
            footnoteNumber = footnoteService.getFootnoteNumber(sourceId);
          }

          // Translate the citation text
          if (shouldTranslate) {
            inTextToInsert = await apiTranslateText(inTextToInsert, "Persian");
            // Note: We don't insert the footnote number into the citation text
            // The footnote will be added separately after the citation
          }
        }

        const newCitedIds = new Set(citedSourceIds).add(sourceId);
        setCitedSourceIds(newCitedIds);

        const onUpdate = () => updateBibliography(newCitedIds);

        // Insert the citation
        await insertCitationWithTracking(sourceId, selectedStyle, inTextToInsert, onUpdate);

        // Handle Vancouver renumbering
        if (selectedStyle.toLowerCase() === "vancouver") {
          await vancouverService.renumberIfNeeded();
        }

        // Check if paragraph was previously red and highlight green
        await Word.run(async (context) => {
          const controls = context.document.contentControls;
          controls.load("items");
          await context.sync();

          for (const control of controls.items) {
            context.load(control, ["tag"]);
            await context.sync();

            if (control.tag === `FISHCHI_CITATION_${sourceId}`) {
              const paragraph = control.paragraphs.getFirst();
              context.load(paragraph, ["uniqueLocalId"]);
              await context.sync();

              // Check if this paragraph was red
              if (highlightingService.isParagraphRed(paragraph.uniqueLocalId)) {
                await highlightingService.highlightParagraphGreen(sourceId);
              }
              break;
            }
          }
        });

        // Show success notification
        notificationService.success("موفقیت", "استناد با موفقیت درج شد");

        // If we have footnote text, insert it after the citation
        if (footnoteText) {
          console.log("Inserting footnote with text:", footnoteText);
          // Move selection to after the citation before inserting footnote
          await Word.run(async (context) => {
            const selection = context.document.getSelection();
            const afterRange = selection.getRange(Word.RangeLocation.after);
            afterRange.select();
            await context.sync();
          });
          await insertFootnote(footnoteText);
        }
      } catch (err: any) {
        const errorMessage = err.message || "Failed to insert citation";
        setError(errorMessage);
        notificationService.error("خطا در درج استناد", errorMessage);
      } finally {
        setIsInserting(null);
      }
    },
    [
      isInserting,
      sources,
      selectedStyle,
      translatedFootnotesAdded,
      citedSourceIds,
      updateBibliography,
      setError,
    ]
  );

  // Remove citation handler
  const removeCitationHandler = React.useCallback(
    async (sourceId: string) => {
      if (isInserting) return;

      setIsInserting(sourceId);
      setError(null);
      try {
        // Highlight paragraphs red before removal
        await highlightingService.highlightParagraphRed(sourceId);

        const newCitedIds = new Set(citedSourceIds);
        newCitedIds.delete(sourceId);
        setCitedSourceIds(newCitedIds);

        const onUpdate = () => updateBibliography(newCitedIds);
        await removeCitation(sourceId, onUpdate);

        // Show success notification
        notificationService.success("موفقیت", "استناد با موفقیت حذف شد");
      } catch (err: any) {
        const errorMessage = err.message || "Failed to remove citation";
        setError(errorMessage);
        notificationService.error("خطا در حذف استناد", errorMessage);
      } finally {
        setIsInserting(null);
      }
    },
    [isInserting, citedSourceIds, updateBibliography, setError]
  );

  // Insert bibliography handler
  const insertBibliography = React.useCallback(async () => {
    if (citedSourceIds.size === 0) {
      setError("ابتدا باید حداقل یک منبع را درج کنید.");
      return;
    }
    setIsInsertingBib(true);
    setError(null);

    try {
      let sourceIds = Array.from(citedSourceIds);

      // For Vancouver, use ordered source IDs based on citation order
      if (selectedStyle.toLowerCase() === "vancouver") {
        const orderedIds = vancouverService.getOrderedSourceIds();
        sourceIds = orderedIds.length > 0 ? orderedIds : sourceIds;
        console.log("Vancouver bibliography order:", sourceIds);
      }

      const citedSources = sources.filter((s) => sourceIds.includes(s._id));

      // Use bibliography formatting service for proper sections and headings
      const bibHtml = await bibFormattingService.formatBibliographyWithSections(
        citedSources,
        sourceIds,
        selectedStyle,
        bibLanguage
      );

      await insertOrReplaceBibliography(bibHtml, sourceIds, selectedStyle);

      // Show notification for Vancouver about manual updates
      if (selectedStyle.toLowerCase() === "vancouver") {
        console.log("Vancouver bibliography inserted. Re-insert if you add new citations.");
        notificationService.info(
          "کتابنامه Vancouver",
          "کتابنامه با موفقیت درج شد. در صورت افزودن استناد جدید، دوباره کتابنامه را درج کنید.",
          7000
        );
      } else {
        notificationService.success("موفقیت", "کتابنامه با موفقیت درج شد");
      }
    } catch (err: any) {
      const errorMessage = err.message || "Failed to create bibliography";
      setError(errorMessage);
      notificationService.error("خطا در ایجاد کتابنامه", errorMessage);
    } finally {
      setIsInsertingBib(false);
    }
  }, [citedSourceIds, sources, bibLanguage, selectedStyle, setError]);

  // Clear all citations handler
  const clearAllCitations = React.useCallback(async () => {
    setIsInserting("clear");
    setError(null);
    try {
      const onUpdate = () => updateBibliography(new Set());
      const idsToRemove = Array.from(citedSourceIds);

      for (const sourceId of idsToRemove) {
        await removeCitation(sourceId, () => Promise.resolve());
      }

      setCitedSourceIds(new Set());
      setTranslatedFootnotesAdded(new Set());
      clearCitationTracking();

      await onUpdate();

      // Show success notification
      notificationService.success("موفقیت", "تمام استنادها با موفقیت پاک شدند");
    } catch (err: any) {
      const errorMessage = err.message || "Failed to clear citations";
      setError(errorMessage);
      notificationService.error("خطا در پاک کردن استنادها", errorMessage);
    } finally {
      setIsInserting(null);
    }
  }, [citedSourceIds, updateBibliography, setError]);

  // Clear bibliography handler
  const clearBibliography = React.useCallback(async () => {
    setIsInserting("clear-bib");
    setError(null);
    try {
      await removeBibliography();

      // Show success notification
      notificationService.success("موفقیت", "کتابنامه با موفقیت پاک شد");
    } catch (err: any) {
      const errorMessage = err.message || "Failed to clear bibliography";
      setError(errorMessage);
      notificationService.error("خطا در پاک کردن کتابنامه", errorMessage);
    } finally {
      setIsInserting(null);
    }
  }, [setError]);

  // Renumber Vancouver handler
  const renumberVancouver = React.useCallback(async () => {
    if (selectedStyle.toLowerCase() !== "vancouver") return;
    setIsInserting("renumber");
    setError(null);
    try {
      // Scan and renumber all Vancouver citations
      await vancouverService.scanAndNumberCitations();

      // Get updated source IDs
      const orderedIds = vancouverService.getOrderedSourceIds();
      const currentCitations = new Set(orderedIds);
      setCitedSourceIds(currentCitations);

      console.log("Vancouver citations renumbered:", orderedIds);

      // Show success notification
      notificationService.success("موفقیت", "شماره‌گذاری مجدد با موفقیت انجام شد");
    } catch (err: any) {
      const errorMessage = err.message || "Failed to renumber citations";
      setError(errorMessage);
      notificationService.error("خطا در شماره‌گذاری مجدد", errorMessage);
    } finally {
      setIsInserting(null);
    }
  }, [selectedStyle, setError]);

  // Insert direct quote handler
  const insertDirectQuote = React.useCallback(
    async (sourceId: string, quoteText: string) => {
      if (isInserting) return;

      setIsInserting(sourceId);
      setError(null);

      try {
        const source = sources.find((s) => s._id === sourceId);
        if (!source) {
          throw new Error("Source not found");
        }

        // Check if source is non-Persian
        const isNonPersian =
          !source.language || !["persian", "fa", "fa-IR"].includes(source.language.toLowerCase());

        // Format author name based on number of authors
        let authorName: string;
        if (source.authors.length === 0) {
          authorName = "نویسنده نامشخص";
        } else if (source.authors.length === 1) {
          authorName = source.authors[0].lastname;
        } else if (source.authors.length === 2) {
          authorName = `${source.authors[0].lastname} و ${source.authors[1].lastname}`;
        } else {
          authorName = `${source.authors[0].lastname} و همکاران`;
        }

        // Translate author name for non-Persian sources
        if (isNonPersian) {
          authorName = await apiTranslateText(authorName, "Persian");
        }

        const year = source.year || "بدون تاریخ";

        // Add footnote with original names (first time only) - only for non-Persian sources
        let footnoteNumber: number | null = null;
        if (isNonPersian) {
          if (!footnoteService.hasFootnote(sourceId)) {
            await footnoteService.prepareFootnoteForTranslation(sourceId, source, selectedStyle);
            footnoteNumber = footnoteService.getFootnoteNumber(sourceId);
          } else {
            footnoteNumber = footnoteService.getFootnoteNumber(sourceId);
          }
        }

        // Format: AuthorName (Year) or AuthorName (Year), "quote text"
        // Note: We don't add the footnote number to the citation text
        // The footnote will be added separately after the citation
        const citationText = `${authorName} (${year})`;
        // Only add quotes if there is actual quote text
        const fullText = quoteText.trim() ? `${citationText}، "${quoteText}"` : citationText;

        // Insert in Word with special tag
        await Word.run(async (context) => {
          const selection = context.document.getSelection();

          // Insert the full text (citation + quote)
          const range = selection.insertText(fullText, Word.InsertLocation.replace);

          // Load the range to get its properties
          context.load(range);
          await context.sync();

          // Wrap the inserted text in a content control
          const control = range.insertContentControl();
          control.tag = `FISHCHI_CITATION_${sourceId}`;
          control.title = `DIRECT_QUOTE_${sourceId}`;
          control.appearance = "BoundingBox"; // Use BoundingBox instead of Tags to avoid placeholder

          await context.sync();
        });

        // Insert actual footnote if needed (only for non-Persian sources and first time)
        if (isNonPersian && footnoteNumber) {
          const footnoteData = footnoteService
            .getAllFootnotes()
            .find((f) => f.sourceId === sourceId);

          if (footnoteData) {
            await Word.run(async (context) => {
              // Find the content control we just created
              const controls = context.document.contentControls;
              controls.load("items");
              await context.sync();

              const control = controls.items.find(
                (c) =>
                  c.tag === `FISHCHI_CITATION_${sourceId}` && c.title === `DIRECT_QUOTE_${sourceId}`
              );

              if (control) {
                // Get the range at the end of author name (before the year)
                const controlRange = control.getRange(Word.RangeLocation.start);

                // Insert footnote at the beginning of the control
                const footnote = controlRange.insertFootnote();
                footnote.body.insertText(footnoteData.originalAuthors, Word.InsertLocation.start);

                await context.sync();
              }
            });
          }
        }

        // Track citation
        const newCitedIds = new Set(citedSourceIds).add(sourceId);
        setCitedSourceIds(newCitedIds);

        console.log(`Direct quote inserted for source ${sourceId}`);

        // Show success notification
        notificationService.success("موفقیت", "نقل قول مستقیم با موفقیت درج شد");
      } catch (err: any) {
        const errorMessage = err.message || "Failed to insert direct quote";
        setError(errorMessage);
        notificationService.error("خطا در درج نقل قول مستقیم", errorMessage);
      } finally {
        setIsInserting(null);
      }
    },
    [isInserting, sources, selectedStyle, citedSourceIds, setError]
  );

  return {
    citedSourceIds,
    setCitedSourceIds,
    selectedStyle,
    setSelectedStyle,
    bibLanguage,
    setBibLanguage,
    autoUpdateBib,
    setAutoUpdateBib,
    isInserting,
    isInsertingBib,
    translatedFootnotesAdded,
    setTranslatedFootnotesAdded,
    insertCitation,
    insertDirectQuote,
    removeCitationHandler,
    insertBibliography,
    clearAllCitations,
    clearBibliography,
    renumberVancouver,
    updateBibliography,
  };
};
