import * as React from "react";
import { Button, Text, Spinner, makeStyles, shorthands } from "@fluentui/react-components";
import { Source } from "../../types/fishchi";
import { EmptyState } from "./EmptyStates";
import { UNASSIGNED_PROJECT_ID } from "../../types/fishchi";
import { designTokens } from "../../theme";
import { HighlightedText } from "../HighlightedText";
import { searchService } from "../../services/searchService";

const useStyles = makeStyles({
  list: {
    flexGrow: 1,
    overflowY: "auto",
    ...shorthands.padding(designTokens.spacing.sm),
    "&::-webkit-scrollbar": {
      width: "8px",
    },
    "&::-webkit-scrollbar-track": {
      backgroundColor: designTokens.colors.surface,
      ...shorthands.borderRadius(designTokens.borderRadius.sm),
    },
    "&::-webkit-scrollbar-thumb": {
      backgroundColor: designTokens.colors.border,
      ...shorthands.borderRadius(designTokens.borderRadius.sm),
      transition: designTokens.transitions.fast,
      "&:hover": {
        backgroundColor: designTokens.colors.borderHover,
      },
    },
  },
  listItem: {
    ...shorthands.padding(designTokens.spacing.md, designTokens.spacing.lg),
    ...shorthands.margin(designTokens.spacing.xs, "0"),
    ...shorthands.borderRadius(designTokens.borderRadius.md),
    cursor: "pointer",
    backgroundColor: designTokens.colors.background,
    ...shorthands.border("1px", "solid", designTokens.colors.border),
    transition: `all ${designTokens.transitions.fast}`,
    "&:hover": {
      backgroundColor: designTokens.colors.status.infoBackground,
      ...shorthands.borderColor(designTokens.colors.primary),
      boxShadow: designTokens.shadows.sm,
      transform: "translateY(-2px)",
    },
    "&:active": {
      transform: "translateY(0)",
    },
  },
  selectedListItem: {
    backgroundColor: designTokens.colors.status.infoBackground,
    ...shorthands.borderColor(designTokens.colors.primary),
    boxShadow: designTokens.shadows.md,
  },
  sourceTitle: {
    fontSize: designTokens.typography.sizes.md,
    fontWeight: designTokens.typography.weights.semibold.toString(),
    color: designTokens.colors.text.primary,
    marginBottom: designTokens.spacing.xs,
    display: "block",
    lineHeight: designTokens.typography.lineHeights.normal.toString(),
  },
  sourceMetadata: {
    fontSize: designTokens.typography.sizes.sm,
    color: designTokens.colors.text.secondary,
    lineHeight: designTokens.typography.lineHeights.tight.toString(),
  },
  actionsContainer: {
    display: "flex",
    ...shorthands.gap(designTokens.spacing.xs),
    marginTop: designTokens.spacing.sm,
    flexWrap: "wrap",
  },
});

interface SourcesListProps {
  sources: Source[];
  selectedSourceId: string | null;
  selectedProjectId: string | null;
  citedSourceIds: Set<string>;
  isInserting: string | null;
  onSourceClick: (sourceId: string) => void;
  onInsertCitation: (sourceId: string, e: React.MouseEvent, shouldTranslate: boolean) => void;
  onRemoveCitation: (sourceId: string) => void;
  onDirectQuote: (sourceId: string, e: React.MouseEvent) => void;
  searchQuery?: string;
}

export const SourcesList: React.FC<SourcesListProps> = ({
  sources,
  selectedSourceId,
  selectedProjectId,
  citedSourceIds,
  isInserting,
  onSourceClick,
  onInsertCitation,
  onRemoveCitation,
  onDirectQuote,
  searchQuery = "",
}) => {
  const styles = useStyles();

  // Filter sources based on search query
  const displayedSources = React.useMemo(() => {
    if (!searchQuery.trim()) {
      return sources;
    }
    const result = searchService.searchSources(sources, searchQuery);
    return result.items;
  }, [sources, searchQuery]);

  if (sources.length === 0) {
    return (
      <EmptyState
        icon="📚"
        message={
          selectedProjectId === UNASSIGNED_PROJECT_ID
            ? "منبع بدون پروژه‌ای یافت نشد"
            : "منبعی در این پروژه یافت نشد"
        }
      />
    );
  }

  return (
    <div className={styles.list}>
      {displayedSources.length === 0 && searchQuery ? (
        <EmptyState icon="🔍" message="منبعی با این جستجو یافت نشد" />
      ) : (
        displayedSources.map((source) => {
          const isNonPersian =
            source.language && !["persian", "fa", "fa-IR"].includes(source.language.toLowerCase());

          return (
            <div
              key={source._id}
              className={`${styles.listItem} ${
                source._id === selectedSourceId ? styles.selectedListItem : ""
              }`}
              onClick={() => onSourceClick(source._id)}
            >
              <Text className={styles.sourceTitle}>
                <HighlightedText text={source.title} query={searchQuery} />
              </Text>
              <Text className={styles.sourceMetadata}>
                <HighlightedText
                  text={`${source.authors.map((a) => a.lastname).join("، ")}${source.year ? ` (${source.year})` : ""}`}
                  query={searchQuery}
                />
              </Text>

              <div className={styles.actionsContainer}>
                {!citedSourceIds.has(source._id) ? (
                  <>
                    <Button
                      size="small"
                      appearance="subtle"
                      onClick={(e) => onInsertCitation(source._id, e, false)}
                      disabled={isInserting === source._id}
                      title="درج استناد (زبان اصلی)"
                    >
                      {isInserting === source._id ? <Spinner size="tiny" /> : "درج استناد"}
                    </Button>
                    {isNonPersian && (
                      <Button
                        size="small"
                        appearance="subtle"
                        onClick={(e) => onInsertCitation(source._id, e, true)}
                        disabled={isInserting === `${source._id}_translate`}
                        title="ترجمه ارجاع به فارسی و درج"
                      >
                        {isInserting === `${source._id}_translate` ? (
                          <Spinner size="tiny" />
                        ) : (
                          "🤖 ترجمه و درج"
                        )}
                      </Button>
                    )}
                    <Button
                      size="small"
                      appearance="subtle"
                      onClick={(e) => onDirectQuote(source._id, e)}
                      disabled={isInserting === `${source._id}_quote`}
                      title="درج نقل قول مستقیم"
                    >
                      {isInserting === `${source._id}_quote` ? (
                        <Spinner size="tiny" />
                      ) : (
                        "📝 نقل قول"
                      )}
                    </Button>
                  </>
                ) : (
                  <>
                    <Button
                      size="small"
                      appearance="subtle"
                      onClick={(e) => onInsertCitation(source._id, e, false)}
                      disabled={isInserting === source._id}
                      title="درج استناد مجدد (زبان اصلی)"
                    >
                      {isInserting === source._id ? <Spinner size="tiny" /> : "درج مجدد"}
                    </Button>
                    {isNonPersian && (
                      <Button
                        size="small"
                        appearance="subtle"
                        onClick={(e) => onInsertCitation(source._id, e, true)}
                        disabled={isInserting === `${source._id}_translate`}
                        title="ترجمه ارجاع به فارسی و درج مجدد"
                      >
                        {isInserting === `${source._id}_translate` ? (
                          <Spinner size="tiny" />
                        ) : (
                          "🤖 ترجمه و درج مجدد"
                        )}
                      </Button>
                    )}
                    <Button
                      size="small"
                      appearance="subtle"
                      onClick={(e) => onDirectQuote(source._id, e)}
                      disabled={isInserting === `${source._id}_quote`}
                      title="درج نقل قول مستقیم"
                    >
                      {isInserting === `${source._id}_quote` ? (
                        <Spinner size="tiny" />
                      ) : (
                        "📝 نقل قول"
                      )}
                    </Button>
                    <Button
                      size="small"
                      appearance="subtle"
                      onClick={(e) => {
                        e.stopPropagation();
                        onRemoveCitation(source._id);
                      }}
                      disabled={isInserting === source._id}
                      title="حذف استناد از متن"
                      style={{ color: "#d13438" }}
                    >
                      حذف استناد
                    </Button>
                  </>
                )}
              </div>
            </div>
          );
        })
      )}
    </div>
  );
};
