/**
 * Service for formatting bibliography with sections and headings
 * Separates Persian and non-Persian sources with appropriate headings
 */

import { Source, CitationStyle } from "../types/fishchi";
import { apiFormatBibliography, apiFormatBibliographyWithOrder } from "./api";
import { vancouverService } from "./vancouverNumberingService";

interface BibliographySection {
  title: string;
  sources: Source[];
  html: string;
}

class BibliographyFormattingService {
  /**
   * Formats bibliography with sections for Persian and non-Persian sources
   */
  async formatBibliographyWithSections(
    sources: Source[],
    sourceIds: string[],
    style: CitationStyle,
    lang: "fa-IR" | "en-US" | "auto"
  ): Promise<string> {
    // For Vancouver, use special formatting without language separation
    if (style.toLowerCase() === "vancouver") {
      return this.formatVancouverBibliography(sourceIds, style);
    }

    // Separate Persian and non-Persian sources
    const persianSources = sources.filter(
      (s) =>
        sourceIds.includes(s._id) &&
        s.language &&
        ["persian", "fa", "fa-IR"].includes(s.language.toLowerCase())
    );

    const nonPersianSources = sources.filter(
      (s) =>
        sourceIds.includes(s._id) &&
        (!s.language || !["persian", "fa", "fa-IR"].includes(s.language.toLowerCase()))
    );

    let html = '<div class="fishchi-bibliography">';

    // Main title
    html += `
      <h1 style="font-size: 14pt; font-weight: bold; margin-bottom: 12pt; text-align: center;">
        فهرست منابع
      </h1>
    `;

    // Persian sources section
    if (persianSources.length > 0) {
      html += `
        <h2 style="font-size: 12pt; font-weight: bold; margin-top: 8pt; margin-bottom: 8pt;">
          الف. منابع فارسی
        </h2>
      `;

      const persianIds = persianSources.map((s) => s._id);
      const persianHtml = await apiFormatBibliography(persianIds, style, "fa-IR");
      html += persianHtml;
    }

    // Non-Persian sources section
    if (nonPersianSources.length > 0) {
      html += `
        <h2 style="font-size: 12pt; font-weight: bold; margin-top: 8pt; margin-bottom: 8pt;">
          ب. منابع انگلیسی
        </h2>
      `;

      const nonPersianIds = nonPersianSources.map((s) => s._id);
      const nonPersianHtml = await apiFormatBibliography(nonPersianIds, style, "en-US");
      html += nonPersianHtml;
    }

    html += "</div>";
    return html;
  }

  /**
   * Formats Vancouver bibliography without language separation
   */
  private async formatVancouverBibliography(
    sourceIds: string[],
    style: CitationStyle
  ): Promise<string> {
    // Scan and get ordered source IDs from Vancouver service
    await vancouverService.scanAndNumberCitations();
    const orderedIds = vancouverService.getOrderedSourceIds();
    const finalIds = orderedIds.length > 0 ? orderedIds : sourceIds;

    console.log("Vancouver bibliography - ordered IDs:", finalIds);

    let html = '<div class="fishchi-bibliography">';

    // Main title
    html += `
      <h1 style="font-size: 14pt; font-weight: bold; margin-bottom: 12pt; text-align: center;">
        منابع
      </h1>
    `;

    // ✅ FIX: Use apiFormatBibliographyWithOrder to pass citation order
    const bibHtml = await apiFormatBibliographyWithOrder(finalIds, style, "auto", finalIds);
    html += bibHtml;

    html += "</div>";
    return html;
  }

  /**
   * Checks if a source is Persian
   */
  isPersianSource(source: Source): boolean {
    return (
      source.language !== undefined &&
      ["persian", "fa", "fa-IR"].includes(source.language.toLowerCase())
    );
  }
}

export const bibFormattingService = new BibliographyFormattingService();
