/**
 * Help Modal Component
 * Displays help information and keyboard shortcuts
 */

import * as React from "react";
import {
  Dialog,
  DialogSurface,
  DialogBody,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Text,
  makeStyles,
  shorthands,
  Accordion,
  AccordionItem,
  AccordionHeader,
  AccordionPanel,
} from "@fluentui/react-components";
import { designTokens } from "../theme";

const useStyles = makeStyles({
  content: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.md),
  },
  section: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.sm),
  },
  shortcutItem: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    ...shorthands.padding(designTokens.spacing.sm),
    backgroundColor: designTokens.colors.surface,
    ...shorthands.borderRadius(designTokens.borderRadius.sm),
  },
  kbd: {
    ...shorthands.padding("2px", "6px"),
    backgroundColor: designTokens.colors.background,
    ...shorthands.border("1px", "solid", designTokens.colors.border),
    ...shorthands.borderRadius(designTokens.borderRadius.sm),
    fontFamily: "monospace",
    fontSize: designTokens.typography.sizes.sm,
  },
});

interface HelpModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const HelpModal: React.FC<HelpModalProps> = ({ isOpen, onClose }) => {
  const styles = useStyles();

  return (
    <Dialog open={isOpen} onOpenChange={(_, data) => !data.open && onClose()}>
      <DialogSurface style={{ maxWidth: "600px" }}>
        <DialogBody>
          <DialogTitle>راهنمای استفاده از فیشچی</DialogTitle>
          <DialogContent>
            <div className={styles.content}>
              <Accordion collapsible>
                {/* Getting Started */}
                <AccordionItem value="getting-started">
                  <AccordionHeader>شروع کار</AccordionHeader>
                  <AccordionPanel>
                    <div className={styles.section}>
                      <Text>
                        1. یک پروژه را از لیست انتخاب کنید یا "بدون پروژه" را برای منابع عمومی
                        انتخاب کنید
                      </Text>
                      <Text>2. منبع مورد نظر را از لیست پیدا کنید</Text>
                      <Text>3. روی دکمه "درج استناد" کلیک کنید</Text>
                      <Text>4. برای درج کتابنامه، روی دکمه "درج کتابنامه" کلیک کنید</Text>
                    </div>
                  </AccordionPanel>
                </AccordionItem>

                {/* Citation Styles */}
                <AccordionItem value="citation-styles">
                  <AccordionHeader>روش‌های استناددهی</AccordionHeader>
                  <AccordionPanel>
                    <div className={styles.section}>
                      <Text weight="semibold">روش‌های پشتیبانی شده:</Text>
                      <Text>• APA - American Psychological Association</Text>
                      <Text>• MLA - Modern Language Association</Text>
                      <Text>• Chicago - Chicago Manual of Style</Text>
                      <Text>• Harvard - Harvard Referencing</Text>
                      <Text>• Vancouver - Vancouver System</Text>
                      <Text style={{ marginTop: "8px" }}>
                        برای تغییر روش استناددهی، از منوی "تبدیل روش استناددهی" استفاده کنید.
                      </Text>
                    </div>
                  </AccordionPanel>
                </AccordionItem>

                {/* Direct Quotes */}
                <AccordionItem value="direct-quotes">
                  <AccordionHeader>نقل قول مستقیم</AccordionHeader>
                  <AccordionPanel>
                    <div className={styles.section}>
                      <Text>
                        برای درج نقل قول مستقیم، روی دکمه "نقل قول مستقیم" کلیک کنید و متن نقل قول
                        را وارد کنید.
                      </Text>
                      <Text style={{ marginTop: "8px" }}>
                        نقل قول‌های مستقیم در تبدیل روش استناددهی تغییر نمی‌کنند و به همان شکل باقی
                        می‌مانند.
                      </Text>
                    </div>
                  </AccordionPanel>
                </AccordionItem>

                {/* Translation */}
                <AccordionItem value="translation">
                  <AccordionHeader>ترجمه خودکار</AccordionHeader>
                  <AccordionPanel>
                    <div className={styles.section}>
                      <Text>
                        برای منابع غیرفارسی، می‌توانید از گزینه "ترجمه و درج" استفاده کنید تا استناد
                        به فارسی ترجمه شود.
                      </Text>
                      <Text style={{ marginTop: "8px" }}>
                        نام اصلی نویسندگان به صورت خودکار به عنوان زیرنویس اضافه می‌شود.
                      </Text>
                    </div>
                  </AccordionPanel>
                </AccordionItem>

                {/* Keyboard Shortcuts */}
                <AccordionItem value="shortcuts">
                  <AccordionHeader>میانبرهای صفحه‌کلید</AccordionHeader>
                  <AccordionPanel>
                    <div className={styles.section}>
                      <div className={styles.shortcutItem}>
                        <Text>درج استناد</Text>
                        <span className={styles.kbd}>Ctrl+Shift+C</span>
                      </div>
                      <div className={styles.shortcutItem}>
                        <Text>درج کتابنامه</Text>
                        <span className={styles.kbd}>Ctrl+Shift+B</span>
                      </div>
                      <div className={styles.shortcutItem}>
                        <Text>بروزرسانی</Text>
                        <span className={styles.kbd}>Ctrl+Shift+R</span>
                      </div>
                      <div className={styles.shortcutItem}>
                        <Text>جستجو</Text>
                        <span className={styles.kbd}>Ctrl+Shift+F</span>
                      </div>
                    </div>
                  </AccordionPanel>
                </AccordionItem>

                {/* Tips */}
                <AccordionItem value="tips">
                  <AccordionHeader>نکات و ترفندها</AccordionHeader>
                  <AccordionPanel>
                    <div className={styles.section}>
                      <Text>• از تب "منابع سند" برای مشاهده منابع استفاده شده استفاده کنید</Text>
                      <Text>• می‌توانید روی هر استناد کلیک کنید تا به محل آن در سند بروید</Text>
                      <Text>
                        • برای Vancouver، پس از افزودن استناد جدید، کتابنامه را دوباره درج کنید
                      </Text>
                      <Text>• از جستجو برای پیدا کردن سریع منابع استفاده کنید</Text>
                      <Text>
                        • می‌توانید چندین استناد از یک منبع داشته باشید و همه آنها به صورت خودکار
                        مدیریت می‌شوند
                      </Text>
                    </div>
                  </AccordionPanel>
                </AccordionItem>
              </Accordion>
            </div>
          </DialogContent>
          <DialogActions>
            <Button appearance="primary" onClick={onClose}>
              بستن
            </Button>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  );
};
