/**
 * Service for managing footnotes for translated citations
 * Adds original author names as footnotes when citations are translated
 */

/* global Word */

import { Source, CitationStyle } from "../types/fishchi";

interface FootnoteTracker {
  sourceId: string;
  footnoteNumber: number;
  originalAuthors: string;
  addedAt: Date;
}

class CitationFootnoteService {
  private footnotes: Map<string, FootnoteTracker> = new Map();

  /**
   * Prepares footnote data for a translated citation
   * Returns the footnote text that should be added
   * Only prepares if not already added and style is not Vancouver
   */
  async prepareFootnoteForTranslation(
    sourceId: string,
    source: Source,
    citationStyle: CitationStyle
  ): Promise<string | null> {
    // Skip for Vancouver style
    if (citationStyle.toLowerCase() === "vancouver") {
      console.log("Skipping footnote for Vancouver style");
      return null;
    }

    // Check if footnote already exists
    if (this.footnotes.has(sourceId)) {
      console.log(`Footnote already prepared for source ${sourceId}`);
      return null; // Already added
    }

    // Format original author names
    const originalAuthors = this.formatOriginalAuthors(source);

    // Track that we've prepared this footnote
    const nextNumber = this.footnotes.size + 1;
    this.footnotes.set(sourceId, {
      sourceId,
      footnoteNumber: nextNumber,
      originalAuthors,
      addedAt: new Date(),
    });

    console.log(`Prepared footnote for source ${sourceId}: ${originalAuthors}`);
    return originalAuthors;
  }

  /**
   * Formats original author names from source
   * Returns only last names in the format: "Smith", "Smith & Snow", or "Smith et al."
   */
  private formatOriginalAuthors(source: Source): string {
    if (!source.authors || source.authors.length === 0) {
      return "Unknown Author";
    }

    // Single author: just lastname
    if (source.authors.length === 1) {
      return source.authors[0].lastname;
    }

    // Two authors: "Lastname1 & Lastname2"
    if (source.authors.length === 2) {
      return `${source.authors[0].lastname} & ${source.authors[1].lastname}`;
    }

    // Three or more authors: "Lastname et al."
    return `${source.authors[0].lastname} et al.`;
  }

  /**
   * Prepares footnote text but doesn't insert it yet
   * Returns the footnote number that will be used
   */
  private async insertFootnoteInWord(text: string): Promise<number> {
    // For now, we'll return a placeholder number
    // The actual footnote will be inserted by Word when we use the [number] format
    // We need to track the next available footnote number
    const nextNumber = this.footnotes.size + 1;
    console.log(`Prepared footnote text (will use number ${nextNumber}): ${text}`);
    return nextNumber;
  }

  /**
   * Actually inserts the footnote in Word at a specific location
   */
  async insertFootnoteAtLocation(text: string, range: Word.Range): Promise<number> {
    return await Word.run(async (context) => {
      const footnote = range.insertFootnote();
      footnote.body.insertText(text, Word.InsertLocation.start);

      // Get footnote reference to extract number
      context.load(footnote, "reference");
      await context.sync();

      // Extract number from reference text
      const refText = footnote.reference.text;
      const number = parseInt(refText.match(/\d+/)?.[0] || "1");

      console.log(`Inserted footnote with number: ${number}`);
      return number;
    });
  }

  /**
   * Checks if a footnote exists for a source
   */
  hasFootnote(sourceId: string): boolean {
    return this.footnotes.has(sourceId);
  }

  /**
   * Gets the footnote number for a source
   */
  getFootnoteNumber(sourceId: string): number | null {
    const footnote = this.footnotes.get(sourceId);
    return footnote ? footnote.footnoteNumber : null;
  }

  /**
   * Clears all footnote tracking
   */
  clearFootnotes(): void {
    this.footnotes.clear();
    console.log("Cleared all footnote tracking");
  }

  /**
   * Gets all tracked footnotes
   */
  getAllFootnotes(): FootnoteTracker[] {
    return Array.from(this.footnotes.values());
  }
}

// Export singleton instance
export const footnoteService = new CitationFootnoteService();
