/**
 * Export Service
 * Handles document export functionality
 */

class ExportService {
  /**
   * Export document as PDF (using Word's built-in functionality)
   */
  async exportAsPDF(): Promise<void> {
    try {
      await Word.run(async (context) => {
        // Get document properties
        const properties = context.document.properties;
        context.load(properties, "title");
        await context.sync();

        const title = properties.title || "document";
        const filename = `${title}-${new Date().toISOString().split("T")[0]}.pdf`;

        console.log("Preparing PDF export:", filename);

        // Note: Word Add-ins cannot directly export to PDF
        // This would require Office.js APIs that may not be available
        // Alternative: Guide user to use File > Save As > PDF

        throw new Error(
          "PDF export must be done manually: File > Save As > PDF\n" +
            "افزونه نمی‌تواند مستقیماً PDF ایجاد کند. لطفاً از منوی File > Save As > PDF استفاده کنید."
        );
      });
    } catch (error) {
      console.error("PDF export failed:", error);
      throw error;
    }
  }

  /**
   * Export document content as HTML
   */
  async exportAsHTML(): Promise<string> {
    try {
      return await Word.run(async (context) => {
        const body = context.document.body;
        const html = body.getHtml();
        await context.sync();

        console.log("Document exported as HTML");
        return html.value;
      });
    } catch (error) {
      console.error("HTML export failed:", error);
      throw error;
    }
  }

  /**
   * Export citations list as text
   */
  async exportCitationsList(citedSourceIds: string[], sources: any[]): Promise<string> {
    try {
      const citedSources = sources.filter((s) => citedSourceIds.includes(s._id));

      let text = "لیست منابع استفاده شده\n";
      text += "=".repeat(50) + "\n\n";

      citedSources.forEach((source, index) => {
        text += `${index + 1}. ${source.title}\n`;
        text += `   نویسندگان: ${source.authors.map((a: any) => a.lastname).join("، ")}\n`;
        text += `   سال: ${source.year || "نامشخص"}\n\n`;
      });

      console.log("Citations list exported");
      return text;
    } catch (error) {
      console.error("Citations list export failed:", error);
      throw error;
    }
  }

  /**
   * Download text content as file
   */
  downloadTextFile(content: string, filename: string): void {
    const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    console.log("File downloaded:", filename);
  }
}

export const exportService = new ExportService();
