import * as React from "react";
import {
  Dialog,
  DialogSurface,
  DialogBody,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Field,
  Dropdown,
  Option,
  Checkbox,
  MessageBar,
  MessageBarBody,
  Spinner,
  makeStyles,
  shorthands,
} from "@fluentui/react-components";
import { CitationStyle } from "../types/fishchi";
import { designTokens } from "../theme";

const useStyles = makeStyles({
  conversionForm: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.md),
  },
});

interface ConversionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConvert: (targetStyle: CitationStyle, translateToFarsi: boolean) => Promise<void>;
  currentStyle: CitationStyle;
}

const CITATION_STYLES: Array<{ value: CitationStyle; label: string }> = [
  { value: "apa", label: "APA" },
  { value: "mla", label: "MLA" },
  { value: "chicago-author-date", label: "Chicago" },
  { value: "harvard-cite-them-right", label: "Harvard" },
  { value: "vancouver", label: "Vancouver" },
];

export const ConversionModal: React.FC<ConversionModalProps> = ({
  isOpen,
  onClose,
  onConvert,
  currentStyle,
}) => {
  const styles = useStyles();
  const [targetStyle, setTargetStyle] = React.useState<CitationStyle>(currentStyle);
  const [translateToFarsi, setTranslateToFarsi] = React.useState(false);
  const [isConverting, setIsConverting] = React.useState(false);

  const handleConvert = async () => {
    setIsConverting(true);
    try {
      await onConvert(targetStyle, translateToFarsi);
      onClose();
    } catch (error) {
      console.error("Conversion failed:", error);
    } finally {
      setIsConverting(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(_, data) => !data.open && onClose()}>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>تبدیل روش استناددهی</DialogTitle>
          <DialogContent>
            <div className={styles.conversionForm}>
              <Field label="روش استناددهی فعلی">
                <div style={{ padding: "8px 0" }}>
                  <strong>
                    {CITATION_STYLES.find((s) => s.value === currentStyle)?.label || currentStyle}
                  </strong>
                </div>
              </Field>

              <Field label="روش استناددهی مقصد" required>
                <Dropdown
                  value={CITATION_STYLES.find((s) => s.value === targetStyle)?.label || targetStyle}
                  onOptionSelect={(_, data) => setTargetStyle(data.optionValue as CitationStyle)}
                  disabled={isConverting}
                >
                  {CITATION_STYLES.map((style) => (
                    <Option key={style.value} value={style.value}>
                      {style.label}
                    </Option>
                  ))}
                </Dropdown>
              </Field>

              <Checkbox
                checked={translateToFarsi}
                onChange={(_, data) => setTranslateToFarsi(data.checked as boolean)}
                label="ترجمه استنادهای درون‌متنی به فارسی"
                disabled={isConverting}
              />

              <MessageBar intent="info">
                <MessageBarBody>نقل قول‌های مستقیم در حین تبدیل تغییر نخواهند کرد.</MessageBarBody>
              </MessageBar>
            </div>
          </DialogContent>
          <DialogActions>
            <Button appearance="secondary" onClick={onClose} disabled={isConverting}>
              انصراف
            </Button>
            <Button
              appearance="primary"
              onClick={handleConvert}
              disabled={isConverting || targetStyle === currentStyle}
            >
              {isConverting ? <Spinner size="tiny" /> : "تبدیل"}
            </Button>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  );
};
