import * as React from "react";
import { Avatar, Button, Text, Spinner, makeStyles, shorthands } from "@fluentui/react-components";
import {
  ArrowSyncFilled,
  QuestionCircle20Regular,
  Settings20Regular,
  Bug20Regular,
} from "@fluentui/react-icons";
import { UserProfile, CitationStyle, BibLanguage } from "../../types/fishchi";
import { designTokens } from "../../theme";
import { HelpModal } from "../HelpModal";
import { SettingsModal } from "../SettingsModal";
import { ReportIssueModal } from "../ReportIssueModal";

const useStyles = makeStyles({
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    backgroundColor: designTokens.colors.background,
    ...shorthands.padding(designTokens.spacing.sm, designTokens.spacing.md),
    ...shorthands.borderRadius(designTokens.borderRadius.md),
    boxShadow: designTokens.shadows.sm,
    ...shorthands.gap(designTokens.spacing.sm),
    transition: designTokens.transitions.fast,
  },
  userInfo: {
    display: "flex",
    alignItems: "center",
    ...shorthands.gap(designTokens.spacing.md),
    flexGrow: 1,
  },
  userName: {
    fontSize: designTokens.typography.sizes.lg,
    fontWeight: designTokens.typography.weights.semibold.toString(),
    color: designTokens.colors.text.primary,
  },
  headerButtons: {
    display: "flex",
    alignItems: "center",
    ...shorthands.gap(designTokens.spacing.sm),
  },
  refreshButton: {
    transition: designTokens.transitions.fast,
    "&:hover": {
      backgroundColor: designTokens.colors.backgroundHover,
      transform: "scale(1.05)",
    },
    "&:active": {
      transform: "scale(0.95)",
    },
  },
  logoutButton: {
    minWidth: "80px",
    transition: designTokens.transitions.fast,
    "&:hover": {
      backgroundColor: designTokens.colors.status.errorBackground,
      color: designTokens.colors.status.error,
    },
  },
});

interface HeaderProps {
  user: UserProfile;
  isRefreshing: boolean;
  onRefresh: () => void;
  onLogout: () => void;
  currentStyle: CitationStyle;
  currentLanguage: BibLanguage;
  currentAutoUpdate: boolean;
  onSettingsSave: (settings: {
    defaultStyle: CitationStyle;
    defaultLanguage: BibLanguage;
    autoUpdate: boolean;
  }) => void;
}

export const Header: React.FC<HeaderProps> = ({
  user,
  isRefreshing,
  onRefresh,
  onLogout,
  currentStyle,
  currentLanguage,
  currentAutoUpdate,
  onSettingsSave,
}) => {
  const styles = useStyles();
  const [isHelpOpen, setIsHelpOpen] = React.useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = React.useState(false);
  const [isReportOpen, setIsReportOpen] = React.useState(false);

  return (
    <>
      <HelpModal isOpen={isHelpOpen} onClose={() => setIsHelpOpen(false)} />
      <SettingsModal
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        currentStyle={currentStyle}
        currentLanguage={currentLanguage}
        currentAutoUpdate={currentAutoUpdate}
        onSave={onSettingsSave}
      />
      <ReportIssueModal isOpen={isReportOpen} onClose={() => setIsReportOpen(false)} />
      <div className={styles.header}>
        <div className={styles.userInfo} role="banner" aria-label="اطلاعات کاربر">
          <Avatar
            name={user.username}
            size={40}
            color="brand"
            image={user.avatar ? { src: `https://localhost:5000/${user.avatar}` } : undefined}
            aria-label={`تصویر پروفایل ${user.username}`}
          />
          <Text className={styles.userName} aria-label={`نام کاربری: ${user.username}`}>
            {user.username}
          </Text>
        </div>
        <div className={styles.headerButtons} role="toolbar" aria-label="دکمه‌های هدر">
          <Button
            appearance="subtle"
            icon={isRefreshing ? <Spinner size="tiny" /> : <ArrowSyncFilled />}
            onClick={onRefresh}
            disabled={isRefreshing}
            title="بروزرسانی لیست پروژه‌ها و منابع"
            aria-label="بروزرسانی لیست پروژه‌ها و منابع"
            className={styles.refreshButton}
          >
            {isRefreshing ? "بروزرسانی..." : ""}
          </Button>
          <Button
            appearance="subtle"
            icon={<Settings20Regular />}
            onClick={() => setIsSettingsOpen(true)}
            title="تنظیمات"
            aria-label="نمایش تنظیمات"
          />
          <Button
            appearance="subtle"
            icon={<QuestionCircle20Regular />}
            onClick={() => setIsHelpOpen(true)}
            title="راهنما"
            aria-label="نمایش راهنما"
          />
          <Button
            appearance="subtle"
            icon={<Bug20Regular />}
            onClick={() => setIsReportOpen(true)}
            title="گزارش مشکل"
            aria-label="گزارش مشکل"
          />
          <Button
            appearance="subtle"
            onClick={onLogout}
            className={styles.logoutButton}
            title="خروج از حساب کاربری"
            aria-label="خروج از حساب کاربری"
          >
            خروج
          </Button>
        </div>
      </div>
    </>
  );
};
