/**
 * Settings Modal Component
 * Allows users to configure default settings
 */

import * as React from "react";
import {
  Dialog,
  DialogSurface,
  DialogBody,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Field,
  Dropdown,
  Option,
  Switch,
  makeStyles,
  shorthands,
} from "@fluentui/react-components";
import { CitationStyle, BibLanguage } from "../types/fishchi";
import { designTokens } from "../theme";

const useStyles = makeStyles({
  content: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.md),
  },
  field: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.sm),
  },
});

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentStyle: CitationStyle;
  currentLanguage: BibLanguage;
  currentAutoUpdate: boolean;
  onSave: (settings: {
    defaultStyle: CitationStyle;
    defaultLanguage: BibLanguage;
    autoUpdate: boolean;
  }) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  currentStyle,
  currentLanguage,
  currentAutoUpdate,
  onSave,
}) => {
  const styles = useStyles();
  const [defaultStyle, setDefaultStyle] = React.useState<CitationStyle>(currentStyle);
  const [defaultLanguage, setDefaultLanguage] = React.useState<BibLanguage>(currentLanguage);
  const [autoUpdate, setAutoUpdate] = React.useState(currentAutoUpdate);

  React.useEffect(() => {
    setDefaultStyle(currentStyle);
    setDefaultLanguage(currentLanguage);
    setAutoUpdate(currentAutoUpdate);
  }, [currentStyle, currentLanguage, currentAutoUpdate, isOpen]);

  const handleSave = () => {
    onSave({
      defaultStyle,
      defaultLanguage,
      autoUpdate,
    });
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={(_, data) => !data.open && onClose()}>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>تنظیمات</DialogTitle>
          <DialogContent>
            <div className={styles.content}>
              {/* Default Citation Style */}
              <Field label="روش استناددهی پیش‌فرض">
                <Dropdown
                  value={defaultStyle}
                  selectedOptions={[defaultStyle]}
                  onOptionSelect={(_, data) => setDefaultStyle(data.optionValue as CitationStyle)}
                >
                  <Option value="apa">APA</Option>
                  <Option value="mla">MLA</Option>
                  <Option value="chicago">Chicago</Option>
                  <Option value="harvard">Harvard</Option>
                  <Option value="vancouver">Vancouver</Option>
                </Dropdown>
              </Field>

              {/* Default Bibliography Language */}
              <Field label="زبان پیش‌فرض کتابنامه">
                <Dropdown
                  value={defaultLanguage}
                  selectedOptions={[defaultLanguage]}
                  onOptionSelect={(_, data) => setDefaultLanguage(data.optionValue as BibLanguage)}
                >
                  <Option value="fa-IR">فارسی</Option>
                  <Option value="en-US">انگلیسی</Option>
                  <Option value="auto">خودکار</Option>
                </Dropdown>
              </Field>

              {/* Auto-update Bibliography */}
              <Field label="به‌روزرسانی خودکار کتابنامه">
                <Switch
                  checked={autoUpdate}
                  onChange={(_, data) => setAutoUpdate(data.checked)}
                  label={autoUpdate ? "فعال" : "غیرفعال"}
                />
              </Field>
            </div>
          </DialogContent>
          <DialogActions>
            <Button appearance="secondary" onClick={onClose}>
              انصراف
            </Button>
            <Button appearance="primary" onClick={handleSave}>
              ذخیره
            </Button>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  );
};
