/**
 * Service for managing Vancouver citation numbering
 * Vancouver citations are numbered sequentially based on order of appearance
 */

/* global Word */

interface VancouverCitation {
  sourceId: string;
  number: number;
  position: number;
  contentControlId: number;
}

class VancouverNumberingService {
  private citations: VancouverCitation[] = [];
  private needsRenumbering: boolean = false;

  /**
   * Scans document and assigns numbers to citations based on order
   */
  async scanAndNumberCitations(): Promise<void> {
    await Word.run(async (context) => {
      const contentControls = context.document.contentControls;
      contentControls.load("items");
      await context.sync();

      const citationControls: Array<{
        control: Word.ContentControl;
        sourceId: string;
        position: number;
      }> = [];

      // Load all citation controls
      for (const control of contentControls.items) {
        context.load(control, ["tag", "text", "id"]);
        await context.sync();

        if (control.tag?.startsWith("FISHCHI_CITATION_")) {
          const sourceId = control.tag.replace("FISHCHI_CITATION_", "");

          citationControls.push({
            control,
            sourceId,
            position: citationControls.length, // Use index as position
          });
        }
      }

      // Sort by position in document
      citationControls.sort((a, b) => a.position - b.position);

      // Assign numbers based on first appearance
      const numberMap = new Map<string, number>();
      let currentNumber = 1;

      this.citations = citationControls.map(({ control, sourceId, position }) => {
        let number: number;

        if (numberMap.has(sourceId)) {
          // Reuse existing number for same source
          number = numberMap.get(sourceId)!;
        } else {
          // Assign new number
          number = currentNumber++;
          numberMap.set(sourceId, number);
        }

        return {
          sourceId,
          number,
          position,
          contentControlId: control.id,
        };
      });

      // Update citation text with numbers
      for (let i = 0; i < citationControls.length; i++) {
        const { control } = citationControls[i];
        const { number } = this.citations[i];

        control.clear();
        control.insertText(`[${number}]`, Word.InsertLocation.start);
      }

      await context.sync();
      console.log("Vancouver citations numbered:", this.citations);
    });
  }

  /**
   * Inserts a citation with Vancouver numbering
   */
  async insertCitationWithNumber(
    sourceId: string,
    position: "current" | "end" = "current"
  ): Promise<number> {
    // Check if source already has a number
    const existingCitation = this.citations.find((c) => c.sourceId === sourceId);

    if (existingCitation) {
      // Reuse existing number
      console.log(`Reusing Vancouver number ${existingCitation.number} for source ${sourceId}`);
      return existingCitation.number;
    }

    // Assign new number
    const newNumber = this.getNextNumber();
    console.log(`Assigned new Vancouver number ${newNumber} for source ${sourceId}`);

    // If inserting in middle, mark for renumbering
    if (position === "current") {
      this.needsRenumbering = true;
    }

    return newNumber;
  }

  /**
   * Gets the next available number
   */
  private getNextNumber(): number {
    if (this.citations.length === 0) return 1;
    const maxNumber = Math.max(...this.citations.map((c) => c.number));
    return maxNumber + 1;
  }

  /**
   * Renumbers all citations if needed
   */
  async renumberIfNeeded(): Promise<void> {
    if (this.needsRenumbering) {
      console.log("Renumbering Vancouver citations...");
      await this.scanAndNumberCitations();
      this.needsRenumbering = false;
    }
  }

  /**
   * Gets the citation number for a source
   */
  getCitationNumber(sourceId: string): number | null {
    const citation = this.citations.find((c) => c.sourceId === sourceId);
    return citation?.number || null;
  }

  /**
   * Gets source IDs in order of first appearance
   */
  getOrderedSourceIds(): string[] {
    const seen = new Set<string>();
    return this.citations
      .filter((c) => {
        if (seen.has(c.sourceId)) return false;
        seen.add(c.sourceId);
        return true;
      })
      .map((c) => c.sourceId);
  }

  /**
   * Clears all tracking
   */
  clear(): void {
    this.citations = [];
    this.needsRenumbering = false;
    console.log("Cleared Vancouver numbering");
  }

  /**
   * Gets all citations
   */
  getAllCitations(): VancouverCitation[] {
    return [...this.citations];
  }
}

// Export singleton instance
export const vancouverService = new VancouverNumberingService();
