/**
 * Custom Theme Provider for Fishchi Word Add-in
 * Extends Fluent UI 2 with custom design tokens
 */

import * as React from "react";
import {
  FluentProvider,
  Theme,
  webLightTheme,
  createLightTheme,
  BrandVariants,
} from "@fluentui/react-components";
import { designTokens } from "./designTokens";

// Create custom brand variants based on our primary color
const fishchiBrandVariants: BrandVariants = {
  10: "#061724",
  20: "#0c2d47",
  30: "#11426a",
  40: "#16578d",
  50: "#1b6cb0",
  60: "#0078d4", // Primary
  70: "#2b88d8",
  80: "#5098dc",
  90: "#75a8e0",
  100: "#9ab8e4",
  110: "#bfc8e8",
  120: "#e4d8ec",
  130: "#f0e8f0",
  140: "#f8f4f8",
  150: "#fcfafc",
  160: "#ffffff",
};

// Create custom light theme
const fishchiTheme: Theme = {
  ...createLightTheme(fishchiBrandVariants),

  // Override with our custom tokens
  colorNeutralForeground1: designTokens.colors.text.primary,
  colorNeutralForeground2: designTokens.colors.text.secondary,
  colorNeutralForeground3: designTokens.colors.text.tertiary,
  colorNeutralForegroundDisabled: designTokens.colors.text.disabled,

  colorNeutralBackground1: designTokens.colors.background,
  colorNeutralBackground2: designTokens.colors.surface,

  colorBrandForeground1: designTokens.colors.primary,
  colorBrandForeground2: designTokens.colors.primaryHover,

  colorNeutralStroke1: designTokens.colors.border,
  colorNeutralStroke2: designTokens.colors.borderHover,

  colorPaletteGreenForeground1: designTokens.colors.status.success,
  colorPaletteRedForeground1: designTokens.colors.status.error,
  colorPaletteYellowForeground1: designTokens.colors.status.warning,

  // Typography
  fontFamilyBase: designTokens.typography.fontFamily,
  fontSizeBase200: designTokens.typography.sizes.xs,
  fontSizeBase300: designTokens.typography.sizes.sm,
  fontSizeBase400: designTokens.typography.sizes.md,
  fontSizeBase500: designTokens.typography.sizes.lg,
  fontSizeBase600: designTokens.typography.sizes.xl,

  fontWeightRegular: designTokens.typography.weights.regular,
  fontWeightMedium: designTokens.typography.weights.medium,
  fontWeightSemibold: designTokens.typography.weights.semibold,
  fontWeightBold: designTokens.typography.weights.bold,

  // Border radius
  borderRadiusSmall: designTokens.borderRadius.sm,
  borderRadiusMedium: designTokens.borderRadius.md,
  borderRadiusLarge: designTokens.borderRadius.lg,

  // Shadows
  shadow2: designTokens.shadows.sm,
  shadow4: designTokens.shadows.sm,
  shadow8: designTokens.shadows.md,
  shadow16: designTokens.shadows.lg,
  shadow28: designTokens.shadows.xl,

  // Transitions
  durationFast: designTokens.transitions.fast,
  durationNormal: designTokens.transitions.normal,
  durationSlow: designTokens.transitions.slow,
};

interface FishchiThemeProviderProps {
  children: React.ReactNode;
}

export const FishchiThemeProvider: React.FC<FishchiThemeProviderProps> = ({ children }) => {
  return <FluentProvider theme={fishchiTheme}>{children}</FluentProvider>;
};

// Export theme for use in makeStyles
export { fishchiTheme };
