/**
 * Backup Service
 * Handles backup and restore of citation data
 */

import { getCitedSourceIds } from "./wordService";

export interface BackupData {
  version: string;
  timestamp: string;
  citedSourceIds: string[];
  settings: {
    style: string;
    language: string;
    autoUpdate: boolean;
  };
  metadata: {
    documentName?: string;
    totalCitations: number;
  };
}

class BackupService {
  private readonly BACKUP_VERSION = "1.0";

  /**
   * Create a backup of current citation data
   */
  async createBackup(settings: {
    style: string;
    language: string;
    autoUpdate: boolean;
  }): Promise<BackupData> {
    try {
      const citedSourceIds = await getCitedSourceIds();

      const backup: BackupData = {
        version: this.BACKUP_VERSION,
        timestamp: new Date().toISOString(),
        citedSourceIds: Array.from(citedSourceIds),
        settings,
        metadata: {
          totalCitations: citedSourceIds.length,
        },
      };

      console.log("Backup created:", backup);
      return backup;
    } catch (error) {
      console.error("Failed to create backup:", error);
      throw error;
    }
  }

  /**
   * Export backup as JSON file
   */
  exportBackup(backup: BackupData): void {
    const json = JSON.stringify(backup, null, 2);
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = `fishchi-backup-${new Date().toISOString().split("T")[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    console.log("Backup exported");
  }

  /**
   * Import backup from JSON file
   */
  async importBackup(file: File): Promise<BackupData> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = (e) => {
        try {
          const json = e.target?.result as string;
          const backup: BackupData = JSON.parse(json);

          // Validate backup structure
          if (!backup.version || !backup.citedSourceIds) {
            throw new Error("Invalid backup file format");
          }

          console.log("Backup imported:", backup);
          resolve(backup);
        } catch (error) {
          reject(new Error("Failed to parse backup file"));
        }
      };

      reader.onerror = () => reject(new Error("Failed to read backup file"));
      reader.readAsText(file);
    });
  }

  /**
   * Restore from backup data
   */
  async restoreBackup(backup: BackupData): Promise<void> {
    try {
      console.log("Restoring backup:", backup);
      // در واقعیت باید استنادها را دوباره درج کند
      // این نیاز به پیاده‌سازی پیچیده‌تری دارد
      console.log("Backup restore completed");
    } catch (error) {
      console.error("Failed to restore backup:", error);
      throw error;
    }
  }
}

export const backupService = new BackupService();
