/**
 * Service for searching sources and notes
 * Provides both client-side and server-side search capabilities
 */

import { Source, Note } from "../types/fishchi";
import { apiSearchSources, apiSearchNotes } from "./api";

export interface SearchResult<T> {
  items: T[];
  totalCount: number;
  query: string;
  highlights: Map<string, string[]>; // item ID -> highlighted fields
}

class SearchService {
  /**
   * Client-side search in sources with fuzzy matching
   */
  searchSources(sources: Source[], query: string): SearchResult<Source> {
    if (!query.trim()) {
      return {
        items: sources,
        totalCount: sources.length,
        query: "",
        highlights: new Map(),
      };
    }

    const lowerQuery = query.toLowerCase();
    const highlights = new Map<string, string[]>();

    const filtered = sources.filter((source) => {
      const matchedFields: string[] = [];

      // Search in title
      if (source.title.toLowerCase().includes(lowerQuery)) {
        matchedFields.push("title");
      }

      // Search in authors
      const authorNames = source.authors
        .map((a) => `${a.firstname || ""} ${a.lastname}`.toLowerCase())
        .join(" ");
      if (authorNames.includes(lowerQuery)) {
        matchedFields.push("authors");
      }

      // Search in year
      if (source.year && source.year.toString().includes(query)) {
        matchedFields.push("year");
      }

      if (matchedFields.length > 0) {
        highlights.set(source._id, matchedFields);
        return true;
      }

      return false;
    });

    return {
      items: filtered,
      totalCount: filtered.length,
      query,
      highlights,
    };
  }

  /**
   * Client-side search in notes
   */
  searchNotes(notes: Note[], query: string): SearchResult<Note> {
    if (!query.trim()) {
      return {
        items: notes,
        totalCount: notes.length,
        query: "",
        highlights: new Map(),
      };
    }

    const lowerQuery = query.toLowerCase();
    const highlights = new Map<string, string[]>();

    const filtered = notes.filter((note) => {
      const matchedFields: string[] = [];

      // Search in content (strip HTML)
      const textContent = this.stripHtml(note.content).toLowerCase();
      if (textContent.includes(lowerQuery)) {
        matchedFields.push("content");
      }

      // Search in tags
      if (note.tags.some((tag) => tag.toLowerCase().includes(lowerQuery))) {
        matchedFields.push("tags");
      }

      if (matchedFields.length > 0) {
        highlights.set(note._id, matchedFields);
        return true;
      }

      return false;
    });

    return {
      items: filtered,
      totalCount: filtered.length,
      query,
      highlights,
    };
  }

  /**
   * Strip HTML tags from content
   */
  private stripHtml(html: string): string {
    const tmp = document.createElement("div");
    tmp.innerHTML = html;
    return tmp.textContent || tmp.innerText || "";
  }

  /**
   * Server-side search for sources
   */
  async searchSourcesOnServer(
    query: string,
    projectId: string | null,
    page: number = 1,
    limit: number = 20
  ): Promise<SearchResult<Source>> {
    const response = await apiSearchSources(query, projectId, page, limit);
    return {
      items: response.sources,
      totalCount: response.totalCount,
      query,
      highlights: new Map(), // Server can provide highlights if implemented
    };
  }

  /**
   * Server-side search for notes
   */
  async searchNotesOnServer(
    query: string,
    projectId: string,
    sourceId: string | null,
    page: number = 1,
    limit: number = 20
  ): Promise<SearchResult<Note>> {
    const response = await apiSearchNotes(query, projectId, sourceId, page, limit);
    return {
      items: response.notes,
      totalCount: response.totalCount,
      query,
      highlights: new Map(),
    };
  }
}

export const searchService = new SearchService();
