import {
  Tab,
  TabList,
  Text,
  Badge,
  TabValue,
  makeStyles,
  shorthands,
} from "@fluentui/react-components";
import { UserProfile, Note, CitationStyle, BibLanguage } from "../../types/fishchi";
import { useAuth } from "../../contexts/AuthContext";
import { checkAndResetIfNewDocument, getUniqueCitedSourceIds } from "../../services/wordService";
import { apiGetNotesBySource } from "../../services/api";
import { insertHtmlAndCitationAfter } from "../../services/wordService";
import { apiFormatCitation, apiTranslateText } from "../../services/api";
import { insertFootnote } from "../../services/wordService";
import { UNASSIGNED_PROJECT_ID } from "../../types/fishchi";

// Hooks
import { useProjects } from "../../hooks/useProjects";
import { useSources } from "../../hooks/useSources";
import { useNotes } from "../../hooks/useNotes";
import { useCitations } from "../../hooks/useCitations";
import { useDocumentSources } from "../../hooks/useDocumentSources";
import { useKeyboardShortcuts } from "../../hooks/useKeyboardShortcuts";

// Components
import { Header } from "./Header";
import { ControlsPanel } from "./ControlsPanel";
import { CitationManagementPanel } from "./CitationManagement";
import { SourcesList } from "./SourcesList";
import { NotesList } from "./NotesList";
import { DocumentSourcesList } from "./DocumentSourcesList";
import { LoadingState, NoProjectsState } from "./EmptyStates";
import { ConversionModal } from "../ConversionModal";
import { DirectQuoteModal } from "../DirectQuoteModal";
import { BibliographyPreviewModal } from "../BibliographyPreviewModal";
import { AdvancedFeaturesModal } from "../AdvancedFeaturesModal";
import { designTokens } from "../../theme";

// Services
import { navigateToCitation } from "../../services/citationNavigationService";
import { footnoteService } from "../../services/citationFootnoteService";
import { vancouverService } from "../../services/vancouverNumberingService";
import { conversionService } from "../../services/styleConversionService";

// --- STYLES ---
const useStyles = makeStyles({
  container: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.sm),
    ...shorthands.padding(designTokens.spacing.sm),
    backgroundColor: designTokens.colors.surface,
    minHeight: "100vh",
    maxHeight: "100vh",
    ...shorthands.overflow("hidden"),
  },
  header: {
    flexShrink: 0,
  },
  controlsPanel: {
    flexShrink: 0,
  },
  tabsContainer: {
    backgroundColor: designTokens.colors.background,
    ...shorthands.padding(designTokens.spacing.sm, designTokens.spacing.md),
    ...shorthands.borderRadius(designTokens.borderRadius.md),
    boxShadow: designTokens.shadows.sm,
    flexShrink: 0,
  },
  tabList: {
    "& button": {
      fontWeight: designTokens.typography.weights.semibold.toString(),
      fontSize: designTokens.typography.sizes.md,
      transition: designTokens.transitions.fast,
      "&:hover": {
        backgroundColor: designTokens.colors.backgroundHover,
      },
    },
  },
  contentCard: {
    backgroundColor: designTokens.colors.background,
    ...shorthands.borderRadius(designTokens.borderRadius.lg),
    boxShadow: designTokens.shadows.md,
    ...shorthands.overflow("hidden"),
    flexGrow: 1,
    flexShrink: 1,
    minHeight: 0,
    display: "flex",
    flexDirection: "column",
  },
  citationManagement: {
    flexShrink: 0,
  },
  notesBadge: {
    marginLeft: designTokens.spacing.sm,
  },
  errorText: {
    color: designTokens.colors.status.error,
    fontWeight: designTokens.typography.weights.semibold.toString(),
    ...shorthands.padding(designTokens.spacing.md),
  },
});

// --- COMPONENT PROPS ---
interface MainWorkspaceProps {
  user: UserProfile;
}

// --- COMPONENT DEFINITION ---
export const MainWorkspace: React.FC<MainWorkspaceProps> = ({ user }) => {
  const styles = useStyles();
  const { logout } = useAuth();

  // Custom Hooks
  const {
    projects,
    selectedProjectId,
    setSelectedProjectId,
    isLoading,
    isRefreshing: isRefreshingProjects,
    error: projectsError,
    setError: setProjectsError,
    fetchProjects,
    unassignedProject,
  } = useProjects(user._id);

  const {
    sources,
    selectedSourceId,
    setSelectedSourceId,
    isRefreshing: isRefreshingSources,
    error: sourcesError,
    setError: setSourcesError,
  } = useSources(selectedProjectId);

  const {
    notes,
    setNotes,
    isRefreshing: isRefreshingNotes,
    error: notesError,
    setError: setNotesError,
  } = useNotes(selectedProjectId, selectedSourceId);

  const {
    citedSourceIds,
    setCitedSourceIds,
    selectedStyle,
    setSelectedStyle,
    bibLanguage,
    setBibLanguage,
    autoUpdateBib,
    setAutoUpdateBib,
    isInserting,
    isInsertingBib,
    translatedFootnotesAdded,
    setTranslatedFootnotesAdded,
    insertCitation,
    insertDirectQuote,
    removeCitationHandler,
    insertBibliography,
    clearAllCitations,
    clearBibliography,
    renumberVancouver,
    updateBibliography,
  } = useCitations(sources, setProjectsError);

  // Document Sources Hook
  const { documentSources, isScanning, refreshDocumentSources } = useDocumentSources(sources);

  // Local State
  const [selectedTab, setSelectedTab] = React.useState<TabValue>("sources");
  const [isConversionModalOpen, setIsConversionModalOpen] = React.useState(false);
  const [isConverting, setIsConverting] = React.useState(false);
  const [isDirectQuoteModalOpen, setIsDirectQuoteModalOpen] = React.useState(false);
  const [directQuoteSourceId, setDirectQuoteSourceId] = React.useState<string | null>(null);
  const [isBibPreviewModalOpen, setIsBibPreviewModalOpen] = React.useState(false);
  const [isAdvancedFeaturesModalOpen, setIsAdvancedFeaturesModalOpen] = React.useState(false);
  const [searchQuery, setSearchQuery] = React.useState<string>("");

  // Combined error state
  const error = projectsError || sourcesError || notesError;
  const isRefreshing = isRefreshingProjects || isRefreshingSources || isRefreshingNotes;

  // --- EFFECTS ---

  // Check if document changed on mount
  React.useEffect(() => {
    checkAndResetIfNewDocument().catch((err) => {
      console.warn("Failed to check document context:", err);
    });
  }, []);

  // Scan document for citations when tab becomes visible
  React.useEffect(() => {
    const syncCitations = async () => {
      try {
        const existingCitations = await getUniqueCitedSourceIds();
        setCitedSourceIds(new Set(existingCitations));
      } catch (err) {
        console.warn("Failed to scan document citations:", err);
      }
    };
    syncCitations();
  }, [setCitedSourceIds]);

  // Switch to notes tab when notes are loaded
  React.useEffect(() => {
    if (notes.length > 0) {
      setSelectedTab("notes");
    }
  }, [notes]);

  // --- EVENT HANDLERS ---

  const handleRefresh = async () => {
    try {
      await fetchProjects();
      const existingCitations = await getUniqueCitedSourceIds();
      setCitedSourceIds(new Set(existingCitations));
    } catch (err: any) {
      setProjectsError(err.message || "خطا در بروزرسانی");
    }
  };

  const handleProjectChange = (e: any, data: { optionValue?: string }) => {
    if (data.optionValue) {
      setSelectedProjectId(data.optionValue);
      setSelectedSourceId(null);
      setNotes([]);
      setProjectsError(null);
    }
  };

  const handleStyleChange = (e: any, data: { optionValue?: string }) => {
    if (data.optionValue) {
      setSelectedStyle(data.optionValue as any);
    }
  };

  const handleBibLanguageChange = (e: any, data: { optionValue?: string }) => {
    if (data.optionValue) {
      setBibLanguage(data.optionValue as any);
    }
  };

  const handleSourceClick = (sourceId: string) => {
    setSelectedSourceId(sourceId);
    setProjectsError(null);
  };

  const handleSettingsSave = (settings: {
    defaultStyle: CitationStyle;
    defaultLanguage: BibLanguage;
    autoUpdate: boolean;
  }) => {
    setSelectedStyle(settings.defaultStyle);
    setBibLanguage(settings.defaultLanguage);
    setAutoUpdateBib(settings.autoUpdate);
    // در واقعیت باید به سرور ارسال شود
    console.log("Settings saved:", settings);
  };

  const handleInsertCitation = async (
    sourceId: string,
    e: React.MouseEvent,
    shouldTranslate: boolean
  ) => {
    e.stopPropagation();
    await insertCitation(sourceId, shouldTranslate);
    // Refresh document sources after insertion
    await refreshDocumentSources();
  };

  const handleLocationClick = async (sourceId: string, locationId: string) => {
    try {
      await navigateToCitation(sourceId, locationId);
    } catch (error) {
      console.error("Failed to navigate to citation:", error);
      setProjectsError("خطا در رفتن به محل استناد");
    }
  };

  const handleReinsertCitation = async (sourceId: string, shouldTranslate: boolean) => {
    await insertCitation(sourceId, shouldTranslate);
    await refreshDocumentSources();
  };

  const handleNoteClick = async (note: Note, shouldTranslate: boolean) => {
    if (isInserting) return;

    const loadingKey = shouldTranslate ? `${note._id}_translate` : note._id;
    // This would need to be handled in the useCitations hook or extracted to a separate handler
    // For now, we'll keep the logic here since it's specific to notes

    setProjectsError(null);

    try {
      const source = sources.find((s) => s._id === note.source);
      if (!source) {
        throw new Error("Source not found");
      }

      const formattedCitation = await apiFormatCitation({
        sourceId: note.source,
        style: selectedStyle,
      });
      const originalInText = formattedCitation.inText;
      let inTextToInsert = originalInText;
      let footnoteNumber: number | null = null;

      // Prepare footnote text for translated citations (except Vancouver)
      let footnoteText: string | null = null;
      if (shouldTranslate && selectedStyle.toLowerCase() !== "vancouver") {
        footnoteText = await footnoteService.prepareFootnoteForTranslation(
          note.source,
          source,
          selectedStyle
        );
        // Get the footnote number that was assigned
        footnoteNumber = footnoteService.getFootnoteNumber(note.source);
      }

      // Translate the citation text
      if (shouldTranslate) {
        inTextToInsert = await apiTranslateText(inTextToInsert, "Persian");

        // Insert footnote number into the translated citation
        if (footnoteNumber) {
          // Pattern: (Author, Year) -> (Author [1], Year)
          const pattern = /\(([^،]+)(،\s*)(\d{4})\)/;
          if (pattern.test(inTextToInsert)) {
            inTextToInsert = inTextToInsert.replace(pattern, `($1 [${footnoteNumber}]$2$3)`);
          }
        }
      }

      const newCitedIds = new Set(citedSourceIds).add(note.source);
      setCitedSourceIds(newCitedIds);

      const onUpdate = () => updateBibliography(newCitedIds);

      await insertHtmlAndCitationAfter(
        note.content,
        note.source,
        selectedStyle,
        inTextToInsert,
        onUpdate
      );

      // If we have footnote text, insert it after the citation
      if (footnoteText) {
        console.log("Inserting footnote with text:", footnoteText);
        // Move selection to after the citation before inserting footnote
        await Word.run(async (context) => {
          const selection = context.document.getSelection();
          const afterRange = selection.getRange(Word.RangeLocation.after);
          afterRange.select();
          await context.sync();
        });
        await insertFootnote(footnoteText);
      }
    } catch (err: any) {
      setProjectsError(err.message || "Failed to insert note");
    }
  };

  // --- RENDER LOGIC ---

  // Conversion handlers
  const handleConvertStyle = () => {
    setIsConversionModalOpen(true);
  };

  const handleConversionSubmit = async (targetStyle: any, translateToFarsi: boolean) => {
    setIsConverting(true);
    try {
      const result = await conversionService.convertCitationStyle(
        selectedStyle,
        targetStyle,
        translateToFarsi,
        sources
      );

      console.log("Conversion completed:", result);

      // Update selected style
      setSelectedStyle(targetStyle);

      // Refresh cited sources
      const existingCitations = await getUniqueCitedSourceIds();
      setCitedSourceIds(new Set(existingCitations));

      // Show success message in console (Office Add-ins don't support alert)
      console.log(
        `✅ تبدیل با موفقیت انجام شد! ${result.convertedCitations} استناد تبدیل شد. ${result.skippedDirectQuotes} نقل قول مستقیم حفظ شد.`
      );

      // Set a temporary success message
      setProjectsError(
        `✅ تبدیل موفق: ${result.convertedCitations} استناد تبدیل شد، ${result.skippedDirectQuotes} نقل قول حفظ شد`
      );

      // Clear success message after 5 seconds
      setTimeout(() => {
        setProjectsError(null);
      }, 5000);
    } catch (err: any) {
      setProjectsError(err.message || "خطا در تبدیل روش استناددهی");
    } finally {
      setIsConverting(false);
    }
  };

  // Direct quote handlers
  const handleDirectQuote = (sourceId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setDirectQuoteSourceId(sourceId);
    setIsDirectQuoteModalOpen(true);
  };

  const handleDirectQuoteInsert = async (quoteText: string) => {
    if (!directQuoteSourceId) return;
    await insertDirectQuote(directQuoteSourceId, quoteText);
  };

  // Keyboard shortcuts
  useKeyboardShortcuts({
    onInsertBibliography: () => {
      if (citedSourceIds.size > 0) {
        insertBibliography();
      }
    },
    onRefresh: handleRefresh,
  });

  if (isLoading) {
    return (
      <div className={styles.container}>
        <LoadingState />
      </div>
    );
  }

  if (projects.length === 0 && !isRefreshing) {
    return (
      <div className={styles.container}>
        <Header
          user={user}
          isRefreshing={isRefreshing}
          onRefresh={handleRefresh}
          onLogout={logout}
          currentStyle={selectedStyle}
          currentLanguage={bibLanguage}
          currentAutoUpdate={autoUpdateBib}
          onSettingsSave={handleSettingsSave}
        />
        <NoProjectsState onRefresh={handleRefresh} isRefreshing={isRefreshing} />
      </div>
    );
  }

  return (
    <div className={styles.container}>
      {/* Header */}
      <div className={styles.header}>
        <Header
          user={user}
          isRefreshing={isRefreshing}
          onRefresh={handleRefresh}
          onLogout={logout}
          currentStyle={selectedStyle}
          currentLanguage={bibLanguage}
          currentAutoUpdate={autoUpdateBib}
          onSettingsSave={handleSettingsSave}
        />
      </div>

      {/* Error Display */}
      {error && <Text className={styles.errorText}>خطا: {error}</Text>}

      {/* Controls Panel */}
      <div className={styles.controlsPanel}>
        <ControlsPanel
          projects={projects}
          selectedProjectId={selectedProjectId}
          selectedStyle={selectedStyle}
          bibLanguage={bibLanguage}
          onProjectChange={handleProjectChange}
          onStyleChange={handleStyleChange}
          onBibLanguageChange={handleBibLanguageChange}
          showProjectSelector={selectedTab !== "document-sources"}
          searchQuery={searchQuery}
          onSearchChange={setSearchQuery}
        />
      </div>

      {/* Tabs */}
      <div className={styles.tabsContainer}>
        <TabList
          className={styles.tabList}
          selectedValue={selectedTab}
          onTabSelect={(_e, d) => setSelectedTab(d.value as TabValue)}
        >
          <Tab value="sources">
            📚 منابع
            {sources.length > 0 && (
              <Badge appearance="filled" color="informative" className={styles.notesBadge}>
                {sources.length}
              </Badge>
            )}
          </Tab>
          <Tab value="notes">
            📝 فیش‌ها
            {notes.length > 0 && (
              <Badge appearance="filled" color="success" className={styles.notesBadge}>
                {notes.length}
              </Badge>
            )}
          </Tab>
          <Tab value="document-sources">
            📄 منابع سند
            {documentSources.length > 0 && (
              <Badge appearance="filled" color="brand" className={styles.notesBadge}>
                {documentSources.length}
              </Badge>
            )}
          </Tab>
        </TabList>
      </div>

      {/* Citation Management Panel */}
      <div className={styles.citationManagement}>
        <CitationManagementPanel
          selectedStyle={selectedStyle}
          autoUpdateBib={autoUpdateBib}
          isInserting={isInserting}
          isInsertingBib={isInsertingBib}
          onInsertBibliography={insertBibliography}
          onRenumberVancouver={renumberVancouver}
          onClearAllCitations={clearAllCitations}
          onClearBibliography={clearBibliography}
          onAutoUpdateChange={setAutoUpdateBib}
          onConvertStyle={handleConvertStyle}
          onPreviewBibliography={() => setIsBibPreviewModalOpen(true)}
          onAdvancedFeatures={() => setIsAdvancedFeaturesModalOpen(true)}
        />
      </div>

      {/* Conversion Modal */}
      <ConversionModal
        isOpen={isConversionModalOpen}
        onClose={() => setIsConversionModalOpen(false)}
        onConvert={handleConversionSubmit}
        currentStyle={selectedStyle}
      />

      {/* Direct Quote Modal */}
      <DirectQuoteModal
        isOpen={isDirectQuoteModalOpen}
        onClose={() => {
          setIsDirectQuoteModalOpen(false);
          setDirectQuoteSourceId(null);
        }}
        source={
          directQuoteSourceId ? sources.find((s) => s._id === directQuoteSourceId) || null : null
        }
        onInsert={handleDirectQuoteInsert}
      />

      {/* Bibliography Preview Modal */}
      <BibliographyPreviewModal
        isOpen={isBibPreviewModalOpen}
        onClose={() => setIsBibPreviewModalOpen(false)}
        citedSourceIds={citedSourceIds}
        sources={sources}
        style={selectedStyle}
        language={bibLanguage}
        onInsert={insertBibliography}
      />

      {/* Advanced Features Modal */}
      <AdvancedFeaturesModal
        isOpen={isAdvancedFeaturesModalOpen}
        onClose={() => setIsAdvancedFeaturesModalOpen(false)}
        citedSourceIds={citedSourceIds}
        sources={sources}
        settings={{
          style: selectedStyle,
          language: bibLanguage,
          autoUpdate: autoUpdateBib,
        }}
      />

      {/* Content Area */}
      <div className={styles.contentCard}>
        {isRefreshing && !isLoading ? (
          <LoadingState message="در حال بارگذاری داده‌ها..." />
        ) : (
          <>
            {selectedTab === "sources" && (
              <SourcesList
                sources={sources}
                selectedSourceId={selectedSourceId}
                selectedProjectId={selectedProjectId}
                citedSourceIds={citedSourceIds}
                isInserting={isInserting}
                onSourceClick={handleSourceClick}
                onInsertCitation={handleInsertCitation}
                onRemoveCitation={removeCitationHandler}
                onDirectQuote={handleDirectQuote}
                searchQuery={searchQuery}
              />
            )}

            {selectedTab === "notes" && (
              <NotesList
                notes={notes}
                sources={sources}
                selectedProjectId={selectedProjectId}
                selectedSourceId={selectedSourceId}
                isInserting={isInserting}
                onNoteClick={handleNoteClick}
                searchQuery={searchQuery}
              />
            )}

            {selectedTab === "document-sources" && (
              <DocumentSourcesList
                documentSources={documentSources}
                onSourceClick={handleSourceClick}
                onLocationClick={handleLocationClick}
                onReinsertCitation={handleReinsertCitation}
                onRemoveCitation={removeCitationHandler}
                isInserting={isInserting}
                searchQuery={searchQuery}
              />
            )}
          </>
        )}
      </div>
    </div>
  );
};
