/**
 * Service for highlighting paragraphs after citation operations
 * Red: after citation removal
 * Green: after citation insertion (if paragraph was red)
 * Default (black): after 2 seconds
 */

/* global Word */

interface HighlightedParagraph {
  paragraphId: string;
  sourceId: string;
  color: "red" | "green" | "default";
  timestamp: Date;
}

class ParagraphHighlightingService {
  private highlights: Map<string, HighlightedParagraph> = new Map();
  private timers: Map<string, NodeJS.Timeout> = new Map();

  /**
   * Highlights paragraph red after citation removal
   */
  async highlightParagraphRed(sourceId: string): Promise<void> {
    await Word.run(async (context) => {
      // Find all content controls for this source
      const controls = context.document.contentControls;
      controls.load("items");
      await context.sync();

      for (const control of controls.items) {
        context.load(control, ["tag"]);
        await context.sync();

        if (control.tag === `FISHCHI_CITATION_${sourceId}`) {
          // Get the paragraph containing this control
          const paragraph = control.paragraphs.getFirst();
          context.load(paragraph, ["uniqueLocalId"]);
          await context.sync();

          // Set red color
          paragraph.font.color = "#d13438";
          await context.sync();

          // Track highlight
          this.highlights.set(paragraph.uniqueLocalId, {
            paragraphId: paragraph.uniqueLocalId,
            sourceId,
            color: "red",
            timestamp: new Date(),
          });

          console.log(`Highlighted paragraph red for source ${sourceId}`);
        }
      }
    });
  }

  /**
   * Highlights paragraph green after citation insertion
   */
  async highlightParagraphGreen(sourceId: string): Promise<void> {
    await Word.run(async (context) => {
      // Find all content controls for this source
      const controls = context.document.contentControls;
      controls.load("items");
      await context.sync();

      for (const control of controls.items) {
        context.load(control, ["tag"]);
        await context.sync();

        if (control.tag === `FISHCHI_CITATION_${sourceId}`) {
          // Get the paragraph containing this control
          const paragraph = control.paragraphs.getFirst();
          context.load(paragraph, ["uniqueLocalId"]);
          await context.sync();

          // Set green color
          paragraph.font.color = "#107c10";
          await context.sync();

          // Update tracking
          this.highlights.set(paragraph.uniqueLocalId, {
            paragraphId: paragraph.uniqueLocalId,
            sourceId,
            color: "green",
            timestamp: new Date(),
          });

          // Schedule transition to default after 2 seconds
          this.scheduleDefaultTransition(paragraph.uniqueLocalId);

          console.log(`Highlighted paragraph green for source ${sourceId}`);
        }
      }
    });
  }

  /**
   * Schedules transition to default color after 2 seconds
   */
  private scheduleDefaultTransition(paragraphId: string): void {
    // Clear existing timer if any
    if (this.timers.has(paragraphId)) {
      clearTimeout(this.timers.get(paragraphId)!);
    }

    // Set new timer
    const timer = setTimeout(async () => {
      await this.resetParagraphColor(paragraphId);
      this.timers.delete(paragraphId);
    }, 2000);

    this.timers.set(paragraphId, timer);
  }

  /**
   * Resets paragraph color to default (black)
   */
  private async resetParagraphColor(paragraphId: string): Promise<void> {
    try {
      await Word.run(async (context) => {
        const paragraphs = context.document.body.paragraphs;
        paragraphs.load("items");
        await context.sync();

        for (const paragraph of paragraphs.items) {
          context.load(paragraph, ["uniqueLocalId"]);
          await context.sync();

          if (paragraph.uniqueLocalId === paragraphId) {
            paragraph.font.color = "#000000"; // Default black
            await context.sync();

            // Update tracking
            const highlight = this.highlights.get(paragraphId);
            if (highlight) {
              highlight.color = "default";
            }

            console.log(`Reset paragraph color to default for ${paragraphId}`);
            break;
          }
        }
      });
    } catch (error) {
      console.error("Error resetting paragraph color:", error);
    }
  }

  /**
   * Checks if a paragraph is currently highlighted red
   */
  isParagraphRed(paragraphId: string): boolean {
    const highlight = this.highlights.get(paragraphId);
    return highlight?.color === "red";
  }

  /**
   * Gets all highlighted paragraphs
   */
  getAllHighlights(): HighlightedParagraph[] {
    return Array.from(this.highlights.values());
  }

  /**
   * Clears all highlights and timers
   */
  clearAllHighlights(): void {
    // Clear all timers
    this.timers.forEach((timer) => clearTimeout(timer));
    this.timers.clear();
    this.highlights.clear();
    console.log("Cleared all paragraph highlights");
  }
}

export const highlightingService = new ParagraphHighlightingService();
