/**
 * Advanced Features Modal
 * Provides access to additional features like backup, export, history
 */

import * as React from "react";
import {
  Dialog,
  DialogSurface,
  DialogBody,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  makeStyles,
  shorthands,
  Text,
} from "@fluentui/react-components";
import {
  ArrowDownload20Regular,
  ArrowUpload20Regular,
  History20Regular,
  DocumentPdf20Regular,
} from "@fluentui/react-icons";
import { designTokens } from "../theme";
import { backupService } from "../services/backupService";
import { exportService } from "../services/exportService";
import { citationHistoryService } from "../services/citationHistoryService";
import { notificationService } from "../services/notificationService";

const useStyles = makeStyles({
  content: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.md),
  },
  featureButton: {
    width: "100%",
    justifyContent: "flex-start",
    ...shorthands.padding(designTokens.spacing.md),
  },
  section: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.sm),
  },
  sectionTitle: {
    fontWeight: designTokens.typography.weights.semibold.toString(),
    marginBottom: designTokens.spacing.xs,
  },
});

interface AdvancedFeaturesModalProps {
  isOpen: boolean;
  onClose: () => void;
  citedSourceIds: Set<string>;
  sources: any[];
  settings: {
    style: string;
    language: string;
    autoUpdate: boolean;
  };
}

export const AdvancedFeaturesModal: React.FC<AdvancedFeaturesModalProps> = ({
  isOpen,
  onClose,
  citedSourceIds,
  sources,
  settings,
}) => {
  const styles = useStyles();
  const fileInputRef = React.useRef<HTMLInputElement>(null);

  const handleExportBackup = async () => {
    try {
      const backup = await backupService.createBackup(settings);
      backupService.exportBackup(backup);
      notificationService.success("موفقیت", "پشتیبان با موفقیت ذخیره شد");
    } catch (error) {
      notificationService.error("خطا", "خطا در ایجاد پشتیبان");
    }
  };

  const handleImportBackup = () => {
    fileInputRef.current?.click();
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const backup = await backupService.importBackup(file);
      notificationService.success(
        "موفقیت",
        `پشتیبان بارگذاری شد (${backup.citedSourceIds.length} استناد)`
      );
      // در واقعیت باید restore شود
    } catch (error) {
      notificationService.error("خطا", "خطا در بارگذاری پشتیبان");
    }
  };

  const handleExportCitationsList = async () => {
    try {
      const text = await exportService.exportCitationsList(Array.from(citedSourceIds), sources);
      exportService.downloadTextFile(text, "citations-list.txt");
      notificationService.success("موفقیت", "لیست استنادها ذخیره شد");
    } catch (error) {
      notificationService.error("خطا", "خطا در ذخیره لیست");
    }
  };

  const handleViewHistory = () => {
    const history = citationHistoryService.getRecentHistory(10);
    const stats = citationHistoryService.getStatistics();
    console.log("Citation History:", history);
    console.log("Statistics:", stats);
    notificationService.info(
      "تاریخچه استنادها",
      `مجموع: ${stats.totalInsertions} درج، ${stats.totalRemovals} حذف`
    );
  };

  const handleExportPDF = async () => {
    try {
      await exportService.exportAsPDF();
    } catch (error: any) {
      notificationService.warning("راهنما", error.message);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(_, data) => !data.open && onClose()}>
      <DialogSurface style={{ maxWidth: "500px" }}>
        <DialogBody>
          <DialogTitle>ویژگی‌های پیشرفته</DialogTitle>
          <DialogContent>
            <div className={styles.content}>
              {/* Backup & Restore */}
              <div className={styles.section}>
                <Text className={styles.sectionTitle}>پشتیبان‌گیری و بازیابی</Text>
                <Button
                  appearance="subtle"
                  icon={<ArrowDownload20Regular />}
                  onClick={handleExportBackup}
                  className={styles.featureButton}
                >
                  ذخیره پشتیبان
                </Button>
                <Button
                  appearance="subtle"
                  icon={<ArrowUpload20Regular />}
                  onClick={handleImportBackup}
                  className={styles.featureButton}
                >
                  بازیابی از پشتیبان
                </Button>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".json"
                  aria-label="انتخاب فایل پشتیبان"
                  style={{ display: "none" }}
                  onChange={handleFileSelect}
                />
              </div>

              {/* History */}
              <div className={styles.section}>
                <Text className={styles.sectionTitle}>تاریخچه</Text>
                <Button
                  appearance="subtle"
                  icon={<History20Regular />}
                  onClick={handleViewHistory}
                  className={styles.featureButton}
                >
                  مشاهده تاریخچه استنادها
                </Button>
              </div>

              {/* Export */}
              <div className={styles.section}>
                <Text className={styles.sectionTitle}>خروجی</Text>
                <Button
                  appearance="subtle"
                  icon={<DocumentPdf20Regular />}
                  onClick={handleExportPDF}
                  className={styles.featureButton}
                >
                  راهنمای خروجی PDF
                </Button>
                <Button
                  appearance="subtle"
                  onClick={handleExportCitationsList}
                  className={styles.featureButton}
                >
                  ذخیره لیست استنادها
                </Button>
              </div>
            </div>
          </DialogContent>
          <DialogActions>
            <Button appearance="primary" onClick={onClose}>
              بستن
            </Button>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  );
};
