import React from "react";
import {
  Dropdown,
  Option,
  Text,
  SearchBox,
  Label,
  makeStyles,
  shorthands,
} from "@fluentui/react-components";
import { Project, CitationStyle } from "../../types/fishchi";
import { CITATION_STYLES, BIBLIOGRAPHY_LANGUAGES, BibLanguage } from "../../types/fishchi";
import { designTokens } from "../../theme";

const useStyles = makeStyles({
  controlsCard: {
    backgroundColor: designTokens.colors.background,
    ...shorthands.padding(designTokens.spacing.sm, designTokens.spacing.md),
    ...shorthands.borderRadius(designTokens.borderRadius.md),
    boxShadow: designTokens.shadows.sm,
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.sm),
  },
  dropdown: {
    width: "100%",
    "& > button": {
      backgroundColor: `${designTokens.colors.background} !important`,
      ...shorthands.border("1px", "solid", designTokens.colors.border),
      ...shorthands.borderRadius(designTokens.borderRadius.md),
      minHeight: "40px",
      transition: designTokens.transitions.fast,
      "&:hover": {
        backgroundColor: `${designTokens.colors.backgroundHover} !important`,
        ...shorthands.borderColor(designTokens.colors.primary),
        boxShadow: designTokens.shadows.sm,
      },
      "&:focus": {
        ...shorthands.borderColor(designTokens.colors.borderFocus),
        boxShadow: `0 0 0 2px ${designTokens.colors.primary}33`,
      },
    },
  },
  searchBox: {
    width: "100%",
    "& input": {
      ...shorthands.borderRadius(designTokens.borderRadius.md),
      fontSize: designTokens.typography.sizes.md,
      transition: designTokens.transitions.fast,
      "&:hover": {
        ...shorthands.borderColor(designTokens.colors.primary),
      },
      "&:focus": {
        boxShadow: `0 0 0 2px ${designTokens.colors.primary}33`,
      },
    },
  },
  sectionLabel: {
    fontSize: designTokens.typography.sizes.sm,
    fontWeight: designTokens.typography.weights.semibold.toString(),
    color: designTokens.colors.text.secondary,
    marginBottom: designTokens.spacing.xs,
    display: "block",
  },
  fieldContainer: {
    marginBottom: "0",
  },
});

interface ControlsPanelProps {
  projects: Project[];
  selectedProjectId: string | null;
  selectedStyle: CitationStyle;
  bibLanguage: BibLanguage;
  onProjectChange: (e: any, data: { optionValue?: string }) => void;
  onStyleChange: (e: any, data: { optionValue?: string }) => void;
  onBibLanguageChange: (e: any, data: { optionValue?: string }) => void;
  showProjectSelector?: boolean;
  searchQuery?: string;
  onSearchChange?: (value: string) => void;
}

export const ControlsPanel: React.FC<ControlsPanelProps> = ({
  projects,
  selectedProjectId,
  selectedStyle,
  bibLanguage,
  onProjectChange,
  onStyleChange,
  onBibLanguageChange,
  showProjectSelector = true,
  searchQuery = "",
  onSearchChange,
}) => {
  const styles = useStyles();

  return (
    <div className={styles.controlsCard}>
      {showProjectSelector && (
        <div className={styles.fieldContainer}>
          <Text className={styles.sectionLabel}>انتخاب پروژه</Text>
          <Dropdown
            className={styles.dropdown}
            placeholder="یک پروژه را انتخاب کنید"
            value={selectedProjectId || ""}
            onOptionSelect={onProjectChange}
          >
            {projects.map((proj) => (
              <Option key={proj._id} value={proj._id} text={proj.title}>
                {proj.title}
              </Option>
            ))}
          </Dropdown>
        </div>
      )}

      <div className={styles.fieldContainer}>
        <Text className={styles.sectionLabel}>استایل استناد</Text>
        <Dropdown
          className={styles.dropdown}
          placeholder="استایل را انتخاب کنید"
          value={selectedStyle}
          onOptionSelect={onStyleChange}
        >
          {CITATION_STYLES.map((style) => (
            <Option key={style.value} value={style.value}>
              {style.label}
            </Option>
          ))}
        </Dropdown>
      </div>

      <div className={styles.fieldContainer}>
        <Text className={styles.sectionLabel}>زبان کتاب‌نامه</Text>
        <Dropdown
          className={styles.dropdown}
          placeholder="زبان کتاب‌نامه را انتخاب کنید"
          value={bibLanguage}
          onOptionSelect={onBibLanguageChange}
        >
          {BIBLIOGRAPHY_LANGUAGES.map((lang) => (
            <Option key={lang.value} value={lang.value}>
              {lang.label}
            </Option>
          ))}
        </Dropdown>
      </div>

      <SearchBox
        className={styles.searchBox}
        placeholder="جستجو در منابع و فیش‌ها..."
        appearance="outline"
        value={searchQuery}
        onChange={(_, data) => onSearchChange?.(data.value || "")}
      />
    </div>
  );
};
