/**
 * DocumentSourcesList Component
 * Displays sources that have been cited in the current document
 */

import * as React from "react";
import { Button, Text, Badge, Spinner, makeStyles, shorthands } from "@fluentui/react-components";
import { ChevronDown20Regular, ChevronUp20Regular, Location20Regular } from "@fluentui/react-icons";
import { DocumentSource } from "../../types/documentSources";
import { designTokens } from "../../theme";
import { EmptyState } from "./EmptyStates";
import { HighlightedText } from "../HighlightedText";
import { searchService } from "../../services/searchService";
import { Source } from "../../types/fishchi";

const useStyles = makeStyles({
  list: {
    flexGrow: 1,
    overflowY: "auto",
    ...shorthands.padding(designTokens.spacing.sm),
    "&::-webkit-scrollbar": {
      width: "8px",
    },
    "&::-webkit-scrollbar-track": {
      backgroundColor: designTokens.colors.surface,
      ...shorthands.borderRadius(designTokens.borderRadius.sm),
    },
    "&::-webkit-scrollbar-thumb": {
      backgroundColor: designTokens.colors.border,
      ...shorthands.borderRadius(designTokens.borderRadius.sm),
      transition: designTokens.transitions.fast,
      "&:hover": {
        backgroundColor: designTokens.colors.borderHover,
      },
    },
  },
  sourceCard: {
    ...shorthands.padding(designTokens.spacing.md, designTokens.spacing.lg),
    ...shorthands.margin(designTokens.spacing.xs, "0"),
    ...shorthands.borderRadius(designTokens.borderRadius.md),
    backgroundColor: designTokens.colors.background,
    ...shorthands.border("1px", "solid", designTokens.colors.border),
    transition: `all ${designTokens.transitions.fast}`,
    "&:hover": {
      boxShadow: designTokens.shadows.sm,
    },
  },
  sourceHeader: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: designTokens.spacing.sm,
  },
  sourceTitle: {
    fontSize: designTokens.typography.sizes.md,
    fontWeight: designTokens.typography.weights.semibold.toString(),
    color: designTokens.colors.text.primary,
    flexGrow: 1,
  },
  citationBadge: {
    marginLeft: designTokens.spacing.sm,
  },
  sourceMetadata: {
    fontSize: designTokens.typography.sizes.sm,
    color: designTokens.colors.text.secondary,
    marginBottom: designTokens.spacing.sm,
  },
  actionsContainer: {
    display: "flex",
    ...shorthands.gap(designTokens.spacing.xs),
    marginTop: designTokens.spacing.sm,
    flexWrap: "wrap",
  },
  citationLocations: {
    marginTop: designTokens.spacing.md,
    ...shorthands.padding(designTokens.spacing.md),
    backgroundColor: designTokens.colors.surface,
    ...shorthands.borderRadius(designTokens.borderRadius.md),
  },
  locationItem: {
    ...shorthands.padding(designTokens.spacing.sm, designTokens.spacing.md),
    ...shorthands.margin(designTokens.spacing.xs, "0"),
    ...shorthands.borderRadius(designTokens.borderRadius.sm),
    backgroundColor: designTokens.colors.background,
    ...shorthands.border("none"),
    width: "100%",
    textAlign: "left",
    cursor: "pointer",
    transition: designTokens.transitions.fast,
    display: "flex",
    alignItems: "center",
    ...shorthands.gap(designTokens.spacing.sm),
    "&:hover": {
      backgroundColor: designTokens.colors.backgroundHover,
      boxShadow: designTokens.shadows.sm,
    },
    "&:focus-visible": {
      ...shorthands.outline("2px", "solid", designTokens.colors.primary),
      outlineOffset: "2px",
    },
  },
  locationPreview: {
    fontSize: designTokens.typography.sizes.sm,
    color: designTokens.colors.text.secondary,
    flexGrow: 1,
    whiteSpace: "nowrap",
    ...shorthands.overflow("hidden"),
    textOverflow: "ellipsis",
  },
  locationNumber: {
    fontSize: designTokens.typography.sizes.sm,
    fontWeight: designTokens.typography.weights.semibold.toString(),
    color: designTokens.colors.primary,
  },
});

interface DocumentSourcesListProps {
  documentSources: DocumentSource[];
  onSourceClick: (sourceId: string) => void;
  onLocationClick: (sourceId: string, locationId: string) => void;
  onReinsertCitation: (sourceId: string, translate: boolean) => void;
  onRemoveCitation: (sourceId: string) => void;
  isInserting: string | null;
  searchQuery?: string;
}

export const DocumentSourcesList: React.FC<DocumentSourcesListProps> = ({
  documentSources,
  onSourceClick,
  onLocationClick,
  onReinsertCitation,
  onRemoveCitation,
  isInserting,
  searchQuery = "",
}) => {
  const styles = useStyles();
  const [expandedSourceId, setExpandedSourceId] = React.useState<string | null>(null);

  // Filter documentSources based on search query
  const displayedDocSources = React.useMemo(() => {
    if (!searchQuery.trim()) {
      return documentSources;
    }
    const sourcesForSearch: Source[] = documentSources.map((ds) => ds.source);
    const result = searchService.searchSources(sourcesForSearch, searchQuery);
    const matchedIds = new Set(result.items.map((s) => s._id));
    return documentSources.filter((ds) => matchedIds.has(ds.sourceId));
  }, [documentSources, searchQuery]);

  if (documentSources.length === 0) {
    return <EmptyState icon="📄" message="هنوز منبعی به این سند اضافه نشده است" />;
  }

  const formatAuthors = (source: any) => {
    return source.authors.map((a: any) => a.lastname).join("، ");
  };

  const isNonPersian = (source: any) => {
    return source.language && !["persian", "fa", "fa-IR"].includes(source.language.toLowerCase());
  };

  return (
    <div className={styles.list} role="list" aria-label="لیست منابع استفاده شده در سند">
      {displayedDocSources.length === 0 && searchQuery ? (
        <EmptyState icon="🔍" message="منبعی با این جستجو یافت نشد" />
      ) : (
        displayedDocSources.map((docSource) => (
          <div
            key={docSource.sourceId}
            className={styles.sourceCard}
            role="listitem"
            aria-label={`منبع: ${docSource.source.title}`}
          >
            <div className={styles.sourceHeader}>
              <Text className={styles.sourceTitle}>
                <HighlightedText text={docSource.source.title} query={searchQuery} />
              </Text>
              <Badge appearance="filled" color="brand" className={styles.citationBadge}>
                {docSource.citationCount} استناد
              </Badge>
            </div>

            <Text className={styles.sourceMetadata}>
              <HighlightedText
                text={`${formatAuthors(docSource.source)}${docSource.source.year ? ` (${docSource.source.year})` : ""}`}
                query={searchQuery}
              />
            </Text>

            <div className={styles.actionsContainer} role="group" aria-label="عملیات منبع">
              <Button
                size="small"
                appearance="subtle"
                onClick={() => onReinsertCitation(docSource.sourceId, false)}
                disabled={isInserting === docSource.sourceId}
                aria-label={`درج مجدد استناد از ${docSource.source.title}`}
              >
                {isInserting === docSource.sourceId ? <Spinner size="tiny" /> : "درج مجدد"}
              </Button>

              {isNonPersian(docSource.source) && (
                <Button
                  size="small"
                  appearance="subtle"
                  onClick={() => onReinsertCitation(docSource.sourceId, true)}
                  disabled={isInserting === `${docSource.sourceId}_translate`}
                  aria-label={`ترجمه و درج مجدد استناد از ${docSource.source.title}`}
                >
                  {isInserting === `${docSource.sourceId}_translate` ? (
                    <Spinner size="tiny" />
                  ) : (
                    "🤖 ترجمه و درج مجدد"
                  )}
                </Button>
              )}

              <Button
                size="small"
                appearance="subtle"
                icon={
                  expandedSourceId === docSource.sourceId ? (
                    <ChevronUp20Regular />
                  ) : (
                    <ChevronDown20Regular />
                  )
                }
                onClick={() =>
                  setExpandedSourceId(
                    expandedSourceId === docSource.sourceId ? null : docSource.sourceId
                  )
                }
                aria-label={`${expandedSourceId === docSource.sourceId ? "بستن" : "باز کردن"} لیست استنادها`}
                aria-expanded={expandedSourceId === docSource.sourceId}
              >
                مشاهده استنادها ({docSource.citationLocations.length})
              </Button>

              <Button
                size="small"
                appearance="subtle"
                onClick={() => onRemoveCitation(docSource.sourceId)}
                disabled={isInserting === `${docSource.sourceId}_remove`}
                title="حذف تمام استنادها به این منبع"
                aria-label={`حذف تمام استنادها به ${docSource.source.title}`}
                style={{ color: "#d13438" }}
              >
                {isInserting === `${docSource.sourceId}_remove` ? (
                  <Spinner size="tiny" />
                ) : (
                  "حذف استناد"
                )}
              </Button>
            </div>

            {expandedSourceId === docSource.sourceId && (
              <div className={styles.citationLocations} aria-label="محل استنادها">
                {docSource.citationLocations.map((location, index) => (
                  <button
                    key={location.id}
                    className={styles.locationItem}
                    onClick={() => onLocationClick(docSource.sourceId, location.id)}
                    aria-label={`رفتن به استناد ${index + 1}: ${location.text}`}
                  >
                    <Location20Regular aria-hidden="true" />
                    <Text className={styles.locationNumber}>استناد {index + 1}</Text>
                    <Text className={styles.locationPreview}>{location.text}</Text>
                  </button>
                ))}
              </div>
            )}
          </div>
        ))
      )}
    </div>
  );
};
