/**
 * Notification Container Component
 * Displays toast notifications
 */

import * as React from "react";
import { makeStyles, shorthands, tokens } from "@fluentui/react-components";
import {
  CheckmarkCircle20Regular,
  ErrorCircle20Regular,
  Warning20Regular,
  Info20Regular,
  Dismiss20Regular,
} from "@fluentui/react-icons";
import { Notification, NotificationType } from "../services/notificationService";
import { useNotifications } from "../hooks/useNotifications";

const useStyles = makeStyles({
  container: {
    position: "fixed",
    top: tokens.spacingVerticalL,
    right: tokens.spacingHorizontalL,
    zIndex: 9999,
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(tokens.spacingVerticalS),
    maxWidth: "400px",
  },
  notification: {
    display: "flex",
    alignItems: "center",
    ...shorthands.gap(tokens.spacingHorizontalM),
    ...shorthands.padding(tokens.spacingVerticalM, tokens.spacingHorizontalM),
    ...shorthands.borderRadius(tokens.borderRadiusMedium),
    boxShadow: tokens.shadow16,
    backgroundColor: tokens.colorNeutralBackground1,
    ...shorthands.border("1px", "solid", tokens.colorNeutralStroke1),
    animation: "slideIn 0.3s ease-out",
  },
  success: {
    ...shorthands.borderColor(tokens.colorPaletteGreenBorder2),
    backgroundColor: tokens.colorPaletteGreenBackground1,
  },
  error: {
    ...shorthands.borderColor(tokens.colorPaletteRedBorder2),
    backgroundColor: tokens.colorPaletteRedBackground1,
  },
  warning: {
    ...shorthands.borderColor(tokens.colorPaletteYellowBorder2),
    backgroundColor: tokens.colorPaletteYellowBackground1,
  },
  info: {
    ...shorthands.borderColor(tokens.colorPaletteBlueBackground2),
    backgroundColor: tokens.colorPaletteBlueBackground2,
  },
  icon: {
    flexShrink: 0,
  },
  message: {
    flexGrow: 1,
    fontSize: tokens.fontSizeBase300,
    lineHeight: tokens.lineHeightBase300,
  },
  dismissButton: {
    flexShrink: 0,
    cursor: "pointer",
    backgroundColor: "transparent",
    ...shorthands.border("none"),
    ...shorthands.padding("4px"),
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    ...shorthands.borderRadius(tokens.borderRadiusMedium),
    color: tokens.colorNeutralForeground2,
    transition: "all 0.2s ease",
    "&:hover": {
      color: tokens.colorNeutralForeground1,
      backgroundColor: tokens.colorNeutralBackground1Hover,
    },
    "&:focus-visible": {
      ...shorthands.outline("2px", "solid", tokens.colorBrandForeground1),
      outlineOffset: "2px",
    },
  },
});

const NotificationItem: React.FC<{
  notification: Notification;
  onDismiss: (id: string) => void;
}> = ({ notification, onDismiss }) => {
  const styles = useStyles();

  const getIcon = () => {
    switch (notification.type) {
      case NotificationType.SUCCESS:
        return <CheckmarkCircle20Regular className={styles.icon} />;
      case NotificationType.ERROR:
        return <ErrorCircle20Regular className={styles.icon} />;
      case NotificationType.WARNING:
        return <Warning20Regular className={styles.icon} />;
      case NotificationType.INFO:
        return <Info20Regular className={styles.icon} />;
    }
  };

  const getTypeClass = () => {
    switch (notification.type) {
      case NotificationType.SUCCESS:
        return styles.success;
      case NotificationType.ERROR:
        return styles.error;
      case NotificationType.WARNING:
        return styles.warning;
      case NotificationType.INFO:
        return styles.info;
    }
  };

  return (
    <div
      className={`${styles.notification} ${getTypeClass()}`}
      role="alert"
      aria-live="assertive"
      aria-atomic="true"
    >
      <div aria-hidden="true">{getIcon()}</div>
      <div className={styles.message}>
        <strong>{notification.title}</strong>
        <br />
        {notification.message}
      </div>
      <button
        className={styles.dismissButton}
        onClick={() => onDismiss(notification.id)}
        aria-label="بستن اعلان"
        title="بستن"
      >
        <Dismiss20Regular aria-hidden="true" />
      </button>
    </div>
  );
};

export const NotificationContainer: React.FC = () => {
  const styles = useStyles();
  const { notifications, dismiss } = useNotifications();

  if (notifications.length === 0) {
    return null;
  }

  return (
    <div className={styles.container} role="region" aria-label="اعلان‌ها" aria-live="polite">
      {notifications.map((notification) => (
        <NotificationItem key={notification.id} notification={notification} onDismiss={dismiss} />
      ))}
    </div>
  );
};
