/**
 * Report Issue Modal Component
 * Allows users to report bugs or issues
 */

import * as React from "react";
import {
  Dialog,
  DialogSurface,
  DialogBody,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Field,
  Textarea,
  Input,
  Dropdown,
  Option,
  Spinner,
  makeStyles,
  shorthands,
} from "@fluentui/react-components";
import { designTokens } from "../theme";
import { notificationService } from "../services/notificationService";
import { apiReportIssue } from "../services/api";

const useStyles = makeStyles({
  content: {
    display: "flex",
    flexDirection: "column",
    ...shorthands.gap(designTokens.spacing.md),
  },
});

interface ReportIssueModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ReportIssueModal: React.FC<ReportIssueModalProps> = ({ isOpen, onClose }) => {
  const styles = useStyles();
  const [issueType, setIssueType] = React.useState("bug");
  const [title, setTitle] = React.useState("");
  const [description, setDescription] = React.useState("");
  const [isSubmitting, setIsSubmitting] = React.useState(false);

  const handleSubmit = async () => {
    if (!title.trim() || !description.trim()) {
      notificationService.warning("خطا", "لطفاً عنوان و توضیحات را وارد کنید");
      return;
    }

    setIsSubmitting(true);
    try {
      // Send to server
      await apiReportIssue({
        type: issueType,
        title,
        description,
      });

      notificationService.success("موفقیت", "گزارش شما با موفقیت ارسال شد");

      // Reset form
      setTitle("");
      setDescription("");
      setIssueType("bug");
      onClose();
    } catch (error) {
      notificationService.error("خطا", "خطا در ارسال گزارش. لطفاً دوباره تلاش کنید");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(_, data) => !data.open && onClose()}>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>گزارش مشکل</DialogTitle>
          <DialogContent>
            <div className={styles.content}>
              {/* Issue Type */}
              <Field label="نوع مشکل">
                <Dropdown
                  value={issueType}
                  selectedOptions={[issueType]}
                  onOptionSelect={(_, data) => setIssueType(data.optionValue as string)}
                >
                  <Option value="bug">باگ / خطا</Option>
                  <Option value="feature">درخواست ویژگی</Option>
                  <Option value="improvement">پیشنهاد بهبود</Option>
                  <Option value="question">سوال</Option>
                  <Option value="other">سایر</Option>
                </Dropdown>
              </Field>

              {/* Title */}
              <Field label="عنوان" required>
                <Input
                  value={title}
                  onChange={(_, data) => setTitle(data.value)}
                  placeholder="عنوان مشکل را وارد کنید"
                  disabled={isSubmitting}
                />
              </Field>

              {/* Description */}
              <Field label="توضیحات" required>
                <Textarea
                  value={description}
                  onChange={(_, data) => setDescription(data.value)}
                  placeholder="توضیحات کامل مشکل را وارد کنید..."
                  rows={6}
                  disabled={isSubmitting}
                />
              </Field>
            </div>
          </DialogContent>
          <DialogActions>
            <Button appearance="secondary" onClick={onClose} disabled={isSubmitting}>
              انصراف
            </Button>
            <Button appearance="primary" onClick={handleSubmit} disabled={isSubmitting}>
              {isSubmitting ? <Spinner size="tiny" /> : "ارسال گزارش"}
            </Button>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  );
};
